window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26413204"]={"book":{"id":26413204,"title":"聪明人用方格笔记本","author":"高桥政史","translator":"袁小雅","publisher":"湖南文艺出版社","pubdate":"2015-6-1","isbn":"9787540471644","tags":["方格笔记本","笔记","效率","效率管理","自我管理","个人管理","思维","学习"],"memCount":11},"np":1,"pb":[14],"idx":[{"i":18640,"t":"如何记笔记，才能让自己变得更聪明？","l":"TF1-1","c":"大梦","g":0,"p":1},{"i":9906,"t":"用框架笔记重构思维方式 ","l":"TF1-2","c":"六六","g":1,"p":1},{"i":8137,"t":"永久记忆","l":"TF1-1","c":"苗青青","g":1,"p":1},{"i":6345,"t":"如何记笔记才能有助于思考","l":"TF1-2","c":"范丹燕","g":1,"p":1},{"i":6161,"t":"用黄金三分法高效做笔记、快速理清思路","l":"TF1-2","c":"洪传霖","g":1,"p":1},{"i":5945,"t":"运用黄金三分法，构建知识框架","l":"TF1-2","c":"碧兰","g":1,"p":1},{"i":5588,"t":"笔记法","l":"TF1-2","c":"陈静","g":1,"p":1},{"i":4962,"t":"用三分法结构笔记助力学习与思考。","l":"TF3-3","c":"李喂喂喂喂","g":1,"p":1},{"i":4725,"t":"这样做笔记，你的思考更具有逻辑性","l":"TF2-2","c":"李明轩","g":0,"p":1},{"i":4587,"t":"思维整理术，方格笔记本","l":"TF1-2","c":"锦莉","g":1,"p":1},{"i":3273,"t":"如何记笔记，才能让自己变得更聪明","l":"TF1-1","c":"大梦","g":0,"p":1},{"i":1697,"t":"如何轻松高效工作","l":"TF1-2","c":"果莉","g":1,"p":1},{"i":1083,"t":"《聪明人用方格笔记本》","l":"TF3-2","c":"丹丹们","g":1,"p":1},{"i":584,"t":"看见你的A2","l":"TF3-1","c":"Emma","g":0,"p":1}],"ms":[{"id":18640,"topic":"如何记笔记，才能让自己变得更聪明？","learn_goal":"","remark":"“拆书”是一种学习的方法论，适用于以提升能力和解决问题为目标的成人学习，拆书是以个人为中心，不是以书中知识为中心，目的是借助书中的知识解决个人的问题，让书中知识成为个人的能力。\n拆书分为个人学习拆书法和组织学习拆书法：个人学习拆书法应用的是RIA便签法，RIA便签法在《这样读书就够了》这本书中有其详细的介绍，让人读一本书就能达到参加同主题培训的效果；组织学习拆书法的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进他人把书中知识拆为己用。\n而“拆书帮”是一个基于拆书法的学习爱好者社群，表现形式为各地的拆书帮分舵。拆书帮分舵是非营利性的学习者组织，他的使命是帮助更多的学习爱好者成为拆书家。\n接下来，我会运用组织学习拆书法为大家带来一个关于“三分法”笔记法的组织学习拆书应用。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"大梦","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>一、自我介绍\u003c/strong> \u003cstrong>1分钟\u003c/strong>\u003c/p>\u003cp>大家好！我是王云梦，大家习惯称呼我：“大梦”，山东北京人。\u003c/p>\u003cp>目前是一名房地产经纪人，俗称“房产中介”，服务的主要区域是海淀区北清路沿线的二手房买卖和上庄镇的房租租赁。\u003c/p>\u003cp>也是一名永达理保险经纪人，结合房产和保险的业务需求，未来2年的拆书方向是“以房养老”，让更多的普通有房族，有机会享受到高品质的养老生活。\u003c/p>\u003cp>现在重新回来拆书，充实生活，提升个人的思维能力、表达能力和总结思考能力。\u003c/p>\u003cp>以上是我的简单介绍，现在介绍一下什么是“拆书”和“拆书帮”。\u003c/p>\u003cp>\u003cstrong>二、拆书帮介绍\u003c/strong> \u003cstrong>2分钟\u003c/strong>\u003c/p>\u003cp>“拆书”是一种学习的方法论，适用于以提升能力和解决问题为目标的成人学习，拆书是以个人为中心，不是以书中知识为中心，目的是借助书中的知识解决个人的问题，让书中知识成为个人的能力。\u003c/p>\u003cp>拆书分为个人学习拆书法和组织学习拆书法：个人学习拆书法应用的是RIA便签法，RIA便签法在《这样读书就够了》这本书中有其详细的介绍，让人读一本书就能达到参加同主题培训的效果；组织学习拆书法的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进他人把书中知识拆为己用。\u003c/p>\u003cp>而“拆书帮”是一个基于拆书法的学习爱好者社群，表现形式为各地的拆书帮分舵。拆书帮分舵是非营利性的学习者组织，他的使命是帮助更多的学习爱好者成为拆书家。\u003c/p>\u003cp>接下来，我会运用组织学习拆书法为大家带来一个关于“三分法”笔记法的组织学习拆书应用。\u003c/p>","ratings_count":1,"texts":[{"id":22945,"quote":null,"explains":"\u003cp>书中介绍的笔记法，不仅具有“视觉效果”，而且记录的内容分门别类，便于迅速抓住学习的重点，也便于“温故而知新”！\u003c/p>\u003cp>现在咱们来一起领略一下他的魅力，让您的笔记也变得聪明好用：\u003c/p>\u003cp>第一步：取一张A4纸，\u003cstrong>横着\u003c/strong>放：今天咱们先用A4纸来体验一下效果，如果用着效果好或者感兴趣，可以网上购买专门的方格笔记本。\u003c/p>\u003cp>第二步：横线切分标题区域：根据自己的书写习惯，在上方区域划条横线，留出合适的标题空间，此空间除了写标题外，还可以写论点或结论、标注日期、作者等内容。\u003c/p>\u003cp>第三步：两条竖线切分功能区：在横线的下方画两条竖线，这样横线的下方区域就被切分成三块区域，左侧区域可以书中原文内容、记录课堂所教学的内容、个人笔记等内容；中间区域记录你对左侧区域的理解、或理顺思路、或摘抄重点等；右侧区域是基于学习到的知识或内容，给自己规划出一个行动方案、行动建议、提升方案、当前工作重点等。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>这个笔记是我2024年11月21日的学习笔记，内容比较凌乱，不愿再看第二眼，内容之间的逻辑也不够清晰。\u003c/p>\u003cp>此篇笔记记录的内容是我听到的培训师分享的内容，没有做进一步的消化吸收，学习效果不是很理想，为对我产生比较大的触动，更没有让我有明显的受益。\u003c/p>\u003cp>下面这篇笔记是我2024年12月31日基于刚才的笔记，利用黄金三分法笔记整理后的笔记。\u003c/p>\u003cp>A2\u003c/p>\u003cp>在准备下周的拆书演练的过程中，我会接着用今天分享的“三分法”笔记法去读书，消化吸收我所学内容。\u003c/p>\u003cp>使用方格笔记本，在上方区域写出总结或主题，下方左侧区域摘录书中原文内容，下方中间区域做出自己的解释，下方右侧区域写出行动方案。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1740325677000,"updated_at":1740468879000},{"id":9906,"topic":"用框架笔记重构思维方式 ","learn_goal":"","remark":"拆书介绍（本次的拆书内容概括）：通过对麦肯锡常用的“空雨伞”方法的介绍，帮助大家改善记笔记的习惯，建立思考模型，更好地理清思路，提高工作和学习的效率。","level":"TF1-2","duration":21,"status":30,"type":0,"chaishujia":{"username":"六六","city":"济南"},"club":{"name":"济南海右分舵","city":"济南"},"prologue":"\u003cp>自我介绍+图书介绍（3分钟）\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是六六，三个标签向您简单推销下我自己。\u003c/p>\u003cp>\u003cstrong>标签1：数字能量学研究爱好者\u003c/strong>。用中国最古老的智慧易经解读数字能量密码，让数字能量为我所用，只为生活得更好。\u003c/p>\u003cp>\u003cstrong>标签2：不断升级的宝妈\u003c/strong>。在宝妈这个终生岗位上，伴随孩子成长会遇到各种各样的挑战，我也一路打怪，育儿技能不断升级，跟着孩子一起成长，感觉自己的生命也重新走了一遍。群里的小伙伴们遇到孩子的问题我们可以一起交流。\u003c/p>\u003cp>\u003cstrong>标签3：未来三级拆书家\u003c/strong>。因为认同，渴望成长，所以不舍追求。感谢赵周老师，感谢拆书帮，让我改变了几十年的读书方式，找到了成长的捷径。从2018年参加第一次拆书活动开始，就是一个陪伴赋能的受益者，希望通过自己努力，能够尽快通关，成为三级拆书家，成为学习促动者，传递这份大爱。\u003c/p>\u003cp>【图书介绍】+【分组】\u003c/p>\u003cp>今天和大家一起分享的这本书来自日本作家高桥政史——《\u003cstrong>聪明人用的方格笔记本\u003c/strong>》。这是一本教我们如何通过记笔记整理大脑思路的书。作者以 “使用方格笔记本、标出题目、用三分法记录笔记”为原则向我们讲述了方格笔记本的使用方法。笔记是我们的“第二大脑”，整理笔记有助于整理大脑内存，理清思路，让我们工作和学习变得生动有趣，轻松顺利。希望通过今天的分享可以帮助大家改善记笔记的习惯，更好地理清思路，提高工作和学习的效率。\u003c/p>\u003cp>今天学习分为3个阶段。首先请大家阅读原文片段，我会进行详细的方法介绍。第二个阶段用瞩目软件把大家随机分成2个小组，请大家在小组里讨论自己以前是怎样记笔记，怎样用笔记思考问题的。邀请1位小伙伴分享自己的经验。第三阶段，请大家写下今天学习后，你将如何应用所学内容？如果时间允许也会邀请一位小伙伴来分享，帮助大家强化学习效果。\u003c/p>","ratings_count":1,"texts":[{"id":13736,"quote":"\u003cp>R: 阅读原文（1.5分钟）\u003c/p>\u003cp>\u003cstrong> 如何利用方格笔记重构思维方式——《聪明人用的方格笔记本》P35-36\u003c/strong>\u003c/p>\u003cp>【黄金三分法之四】——麦肯锡公司的“空・雨・伞”\u003c/p>\u003cp>\u003cstrong> 所谓“空·雨·伞”，其实就是判断何为“空＝现在的情况”，何为“雨＝对此情况的解释”，何为“伞＝根据此解释而采取的行动”。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 首先\u003c/strong>，抬头看天，发现天空中的云朵有些异样，\u003cstrong>解为\u003c/strong>“好像要下雨了”。根据这一解释，\u003cstrong>判断\u003c/strong>应该采取“带伞出门”的行动。这就是“空·雨·伞”。\u003c/p>\u003cp> 看到这里，你可能会说：“什么？这也太简单了！”可是，正是因为大家都觉得这是“再简单不过的事情”，所以未能付诸实践。“简单就是终极的复杂。”这是达・芬奇的一句名言。\u003c/p>\u003cp> “空・雨·伞”这一思考方式（框架）的本质正是麦肯锡的咨询顾问们努力掌握的至简至极的思考法。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导（7分钟）\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>刚才我们看到的片段介绍的就是\u003cstrong>“空·雨·伞\u003c/strong>”。它是通过设立笔记框架的方式重新构建了一种思考方式，将信息、知识有序整理，重点强调经过深度思考的解释和行动，培养逻辑思维习惯，使大脑通过刻意练习不断提升逻辑思维能力\u003cstrong>。\u003c/strong>“空·雨·伞” 是通过简单有效的记笔记方法，提供思考框架，帮助我们简洁有效地整理信息，理清思路，准确地思考和行动，在麦肯锡公司被广泛使用。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>俗话说：“好记性不如烂笔头”，学习和工作中，我们都会用笔记来实现知识和内容的“重现”。好的笔记习惯，能够让内容“活”起来，帮助我们快速聚焦重点，建立解决方案，长期练习能够提升理解和解决问题的逻辑思维力。\u003c/p>\u003cp>如果笔记信息只是照搬板书或者杂乱无章地记录，就可能因为缺乏思考或是没有重点，无法在需要内容重现时提供有价值的信息，表现出来思维混乱无序。假如持续使用这样不得其法的笔记，随着时间的推移，记录的内容都可能遗忘，能力也得不到有效提升，长期来看，还有可能错失人生机遇。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>如何使用这个框架呢？从拆页中我们可以看到其中暗含的三个步骤。这里预置了一个前提条件：准备A4大小的方格本，横向放置，用横竖画三条线，将笔记页分为四个区域（如图所示）。可以用三步走的方式建立一个有用的笔记。\u003c/p>\u003cp>\u003cstrong>1.出门看天空。\u003c/strong>最左边描述天空信息，有没有云？是白云还是乌云？为了便于记忆把这一部分简称为“空”。其实就是记录信息，事实，最左边记录原文再现我们看到或听到的信息。比如听课时记录主讲人讲述的知识点，看书时书中的知识点，会议记录的就是会议内容。类似RIA便签法中的R便签，当然只需要记录关键词。微信群给大家分享上周我学习小伙伴《怎样制造离线时间》拆书课的笔记，可以看到左边是书友分享的原文信息：制造离线时间的方法——\u003cstrong>一固定二延长三常态，四扩习惯成自然。\u003c/strong>\u003c/p>\u003cp>2.\u003cstrong>好像要下雨。\u003c/strong>中间记录看到白云或者乌云之后的判断——今天会下雨吗？简记为“雨”，就是看“天空”之后对原文信息产生的思考、理解或疑问，可以借助5W1h（why、what、where、who、when、How）辅助思考。类似我们的I和A1便签的组合。上周笔记中我记录的就是对自己现状的反思。\u003c/p>\u003cp>3. \u003cstrong>带伞最安全。\u003c/strong>右边记录判定是否下雨之后的行动决定——今天出门带不带伞？是带太阳伞还是雨伞？简记为“伞”，其实就是总结或者具体要去实践的行动计划。类似我们的A2便签。例如上周拆书课我的“伞”部分记的是自己将如使用离线时间的一个行动方案。目前实践了一周，效果还不错。\u003c/p>\u003cp>刚才我提到笔记页要划分为四个区域，第四部分也就是最上端的用法在书中其他地方有提到，用来写标题，这是对笔记的编码，便于日后检索。也有把“伞”的内容放在这个位置的做法，更加强调行动的转化。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>这个方法在日常的工作学习中都能用到，比如我们做方案策划、设计PPT、组织会议都可以用这个框架帮助重塑信息，理清思路。\u003c/p>","interaction":"\u003cp>A1：激活经验（8分钟）\u003c/p>\u003cp>听了刚才的分享，大家有没有下意识的看看自己的笔记呢？请回忆下你是如何记笔记，如何用笔记信息思考问题的呢？请在小组内进行分享，时间每人2分钟。\u003c/p>\u003cp>\u003cstrong>【伙伴分享】\u003c/strong>好的，欢迎回来。刚才有关注到暖暖滴文子一直在使用方格笔记帮助自己思考问题，从中获益良多，可以给我们很好的示范，有请她来分享下自己的经验。\u003c/p>\u003cp>\u003cstrong>文子（职业为儿童美术老师）：\u003c/strong>\u003c/p>\u003cp>今天见到“空雨伞”的笔记结构时，我就发现这跟我平时使用的笔记思考形式是一样的。平时读书或者准备课件的时候，我一直用这样的方法整理思路，个人感觉特别适合于思维拓展。大家可以看下我的笔记本（现场展示），基本上都分成这样三部分：\u003c/p>\u003cp>1.最左边记录书中的信息或者是我要完成的目标。\u003c/p>\u003cp>2.中间部分我会预留大一些，记录我个人头脑风暴产生的各种灵感和思维的拓展。\u003c/p>\u003cp>3.右侧部分的行动内容，我会根据前两部分内容，总结出大纲。这些在我做PPT或者写材料的时候，都能够帮助我快速整理出思路。\u003c/p>\u003cp>谢谢大家，我的分享就这些。\u003c/p>\u003cp>非常谢谢文子的分享。她的笔记习惯非常有效实用，给我们一个正向的引导。她提到用这个方法的三个关键点：一是左边记录原始信息；二是中间记录自己头脑风暴灵感发散时想到的要点，其实这些点不需要有逻辑性，可以把能想到的都列进去，只要能最终引导我们产生右边的行动方案都是可以的。\u003c/p>\u003cp>小文子提到用这样的方式，她可以直接提炼出用于PPT或者写材料的有效信息。这就是我们要用这种方法思维模式想要实现的目标：记录有效的信息，快速提取有价值的内容，最终应用于行动计划。\u003c/p>\u003cp>A2：催化应用（4分钟）\u003c/p>\u003cp>听了小伙伴的分享，大家有没有受到启发呢？请试想一下，一周内如果你要汇报一件工作、参加一次学习，或是听读一本书，按照今天讲到的3个步骤记笔记、建思考框架，你将如何做呢？\u003c/p>\u003cp>给自己定一个行动计划吧！2分钟时间把计划写下来，稍后发到微信群中，与大家一起分享。\u003c/p>\u003cp>还有时间，我们邀请已经写好的朱朱师兄现场分享下，增加大家的理解。\u003c/p>\u003cp>\u003cstrong>朱朱：\u003c/strong>\u003c/p>\u003cp>按照今天学习的内容，我建立了一个跟客户沟通的思维框架。\u003c/p>\u003cp>目标：在下周给客户做画册时，使用空雨伞的方法，提升画册提案的通过率。\u003c/p>\u003cp>行动规划：\u003c/p>\u003cp>1、“空”。客户要做一本有档次的画册。通过现场沟通的方式，询问并记录客户需求的要点。\u003c/p>\u003cp>2、“雨”。根据客户提供的信息，明确“有档次”是什么样的，从中挖出潜藏的要求，判断了解客户审美，猜测他可能喜欢什么样的设计风格，从提供的素材和内容中了解这个画册是为什么而做，什么色彩会合适，最后汇总分析。\u003c/p>\u003cp>3、“伞”。做出3种不同风格的方案（不做全稿，只做小部分稿），供客户从中选择，确定解决方案。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1591356279000,"updated_at":1591596053000,"ria":true},{"id":8137,"topic":"永久记忆","learn_goal":"积累使用“空白的一秒钟”创造“永远无法抹去的记忆”","remark":"你还在为自己明明很认真的做了笔记，却仍然记不住任何内容而百思不得其解吗？\r\n\r\n那么仔细回顾一下你是如何做笔记的？\r\n\r\n是不是一边看着黑板上的板书内容，一边一字不落的照抄在本子上，全程大脑都未参与其中？\r\n\r\n\r\n那么你是时候换一种记笔记的方法啦～\r\n欢迎周日来百新书局，让青青带你一起换一种方法做笔记","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"苗青青","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;自我介绍\r\n大家好，我先跟大家做一下自我介绍，刚刚大家应该已经了解了一部分，我叫青青，欢迎大家来到这次的线下拆书现场。\r\n首先，用三个标签来介绍一下我自己：\r\n第一个标签是“养生少女”，虽然我是个90后，但是我却不喜欢熬夜，喜欢自己煮养生茶、喜欢自己烹饪健康的食物，如果有小伙伴感兴趣的话，我们可以互相交流一下经验，也可以去切磋一下厨艺。\r\n第二个标签是“彩妆爱好者”，前一段时间我报了化妆兴趣班，对化妆开始有了一定的了解，化妆技巧也在实践中不断提升，所以小伙伴们如果有什么化妆心得的话，可以来跟我分享。\r\n第三个标签是“拆书家”，之前3月份的时候，我在百新书局第一次参加l拆书活动，其中有一本书就是今天我要拆的这本书《聪明人用方格笔记本》，接下来的那个周末，参加了师父的全天拆书课《别独自用餐》，被深深吸引，所以三月份的每个周末我都会去参加拆书，现在终于有资格自己来拆书啦，非常开心。\r\n在拆解这本书之前，我先给大家介绍一下什么是拆书，什么是拆书帮，什么是RIA便签法。\r\n什么是拆书？\r\n很多小伙伴第一次听到拆书这个词的时候都会不禁发问：“拆书？是指将书要真的拆掉嘛？”答案当然不是啦，所谓“拆书”是强调将书本中的知识转化为学习者的能力。这是由帮主赵周老师自创的一套阅读方法，不同于以往的以记住书中的知识点为中心的传统阅读方法，该方法主要是运用RIA便签法使大家将书本中的知识拆为己用，从而改变行为、创造价值。\r\n那么什么是RIA便签法呢？\r\n字母R代表reading：该环节是阅读原文拆页。\r\n字母I代表interpretation：该环节是拆书家讲解引导。\r\n字母A代表appropriation：该环节便是“拆为己用”啦，\r\n其中包括三个步骤，分别是A1、A2和A3。\r\nA1指向过去，链接自己过去的经历，可以是成功的，也可以是失败的。\r\nA2指向未来，根据自身情况，制定具体可行的计划。\r\nA3强调当下演练，以期达到参加同主题培训的效果。\r\n什么是拆书帮\r\n拆书帮是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵，我们的运营团队会有舵主、组织长老、宣传长老……而且我们是非营利性的组织。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":11742,"quote":"\u003cp>\u003ca href=\"http://链接:https://pan.baidu.com/s/1I0kCVteL2mTwvAi79cdkhQ\">http://链接:https://pan.baidu.com/s/1I0kCVteL2mTwvAi79cdkhQ &nbsp;密码:67hz\u003cbr>\u003c/p>\u003cp>\u003cstrong>R·\u003c/strong>\u003cstrong>阅读原书拆页【\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟】\u003c/strong>\u003c/p>\u003cp>如果你之前是一边看着老师在黑板上写下的内容，一边原封不动地抄写在笔记本上的话，那么，请你改变一下抄写笔记时的“用眼方法”吧。\u003c/p>\u003cp>将此前：\u003c/p>\u003cp>x“看黑板→写笔记”的记录方法改为“看黑板→印在大脑中→不看黑板，将印在大脑中的内容重现在笔记本上”。不是一边看黑板一边抄写，而是在“看黑板一抄写”之间加入“印在大脑中的一秒钟”。\u003c/p>\u003cp>我把这一秒钟称为“空白的一秒钟”。\u003c/p>\u003cp>只需要这一秒钟，你的笔记本就能升级成能使大脑越变越聪明的笔记本。\u003c/p>\u003cp>当你反复使用这种方法并渐渐地把它变为一种习惯的时候，在你看黑板的那一瞬间，便会自动将你看到的画面印在脑子里，只需“空白的0．01秒”，你便能把看到的内容默写在笔记本上。\u003c/p>\u003cp>更厉害的是，这种“用眼方法”有助于强化“永久记忆”。\u003c/p>\u003cp>刚开始尝试的时候，你也许会觉得这个方法很有难度。\u003c/p>\u003cp>但当你感到不易的时候，其实正是你应该高兴的时候，因为这是你的大脑正在开拓崭新快速记忆回路的证据，“空白的一秒钟”的日积月累将使你产生永远无法抹去的记忆，将使你的快速记忆回路越变越宽。这意味着你正在变为头脑聪明的人。所以请你带上期望与自信，在今天近出第一步，用“空白的一秒钟”创造“水远无法抹去的记忆”吧！\u003c/p>","explains":"\u003cp>\u003cstrong>I\u003c/strong>\u003cstrong>便签【\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟】\u003c/strong>\u003c/p>\u003cp>我先给大家介绍一下这个拆页，我当时看到这本书是在果莉的那个场，她拆了这本书比较重要的“黄金三分法”，然后，我一开始觉的，笔记谁都会做，后来，我听了黄金三分法之后，我去买了这本书，看到它前面罗列了很多错误的记笔记的方法，发现那个人就是我，所以我就把这本书很深刻的读了下去，然后我选择的这份拆页也是因为戳到了我的点吧。\u003c/p>\u003cp>现在我给大家介绍一下：这个拆页的主题是如何巧妙的运用“空白的一秒”去记笔记，并形成永久记忆的“用眼方法”。\u003c/p>\u003cp>不知道大家是否有这样的印象，以前每次考完试的时候，老师都会对名次最后面的学生说，你是不是没有上课认真的把我讲的内容都记下来，然后，有的同学可能真的没有记笔记，但是也会有那么几个学生说，我真的做了笔记，老师让他把笔记拿出来之后，发现他的笔记工工整整，但是呢，他仍然考的一塌糊涂，这个时候老师也不能说什么，只能叹一声气然后说：“你下次好好努力”，以资鼓励。\u003c/p>\u003cp>究竟为什么会出现这样的状况呢？其实并不是说这些学生不努力，而是他们没有使用正确的记笔记的方法。\u003c/p>\u003cp>那么今天的这个拆页就非常适合我们在学习一些有板书、ppt的课程、培训的时候去做笔记。\u003c/p>\u003cp>所以，我们该如何正确的运用这“空白的一秒”去做笔记呢？\u003c/p>\u003cp>首先，看黑板：看老师在黑板上写下的内容或者知识点。\u003c/p>\u003cp>然后，印脑中：将在黑板上看见的内容印入脑海中。\u003c/p>\u003cp>最后，记笔记：将印在脑海中的内容记在笔记本上。\u003c/p>\u003cp>这样记笔记的话，不仅有助于提高记笔记过程的价值、而且加深了对记录的知识点的记忆、并且拓宽了快速记忆的回路，可以使头脑更加聪明。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003cstrong>便签【\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟】\u003c/strong>\u003c/p>\u003cp>接下来给大家分享一个A1的经历，是一个失败的经历。\u003c/p>\u003cp>当时刚步入大学的校门，且由于高考的打击，就像刚刚幻雪分享的间歇性想学习，所以决心发奋图强，好好学习天天向上。然后，大一的时候，你会发现我每堂课每天都会在很认真的记笔记，但是，我所做的笔记基本上只是照抄老师的内容，也就是一边看一边抄的那种，比如说今天我们就是上了一节课，说药学的定义是什么：我可能就是这样，药学是……，这样写下来，所以，每次最后期末考的时候，我还是要去拿着笔记本，毫无头绪的把课本的知识点再重新捋一遍（虽然笔记做了很多，但是什么也没记住），最后考试的时候还很累～\u003c/p>\u003cp>反思一下：\u003c/p>\u003cp>如果我当时在做笔记的时候，不是毫不动脑的将老师黑板上的内容照抄在笔记本上，而是用文中说的“看黑板、印脑中、记笔记”这样的方法的话，期末考的时候也不会那么辛苦了。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>便签【\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟】\u003c/strong>\u003c/p>\u003cp>行动计划：上bec解析课的时候运用这种记笔记的方法\u003c/p>\u003cp>1.时间：6月2日晚上回听这节课的内容\u003c/p>\u003cp>2.地点：卧室\u003c/p>\u003cp>3.人：我\u003c/p>\u003cp>4.内容\u003c/p>\u003cp>1.看黑板：看老师在cctalk课堂上放ppt的内容。\u003c/p>\u003cp>2.印脑中：将ppt的内容印入脑海中，比如说今天讲作文的话，主谓宾要都写好，整个句子，以前我抄句子，像刚刚说的都是边看边抄，现在我要把整个英文句子都记下来，再抄到自己的笔记本上。\u003c/p>\u003cp>3.记笔记：将印在脑海中的内容记在笔记本上。\u003c/p>\u003cp>我觉得用了这个方法之后，我应该就是可以很好的记下老师每天在课上讲到的知识点。\u003c/p>\u003cp>因为我也是1-1定级，所以没有什么互动环节，如果大家有什么提问交流的话，也可以问，如果没有的话，我的拆书就到这里了，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1560341681000,"updated_at":1562508987000,"ria":true},{"id":6345,"topic":"如何记笔记才能有助于思考","learn_goal":"学习者会用“黄金三分法”之一“空雨伞”的框架记笔记","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"范丹燕","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>【自我介绍】1分钟\u003c/p>\u003cp>1-2要求:简要介绍自己和图书，能够完成现场分组。\u003c/p>\u003cp>大家好！我叫范丹燕，非常高兴今天晚上由我来带着大家拆书，根据今天座位情况，咱们四个人一组进行分组。我先用三个标签介绍一下自己：第一个标签是一位与孩子共同成长的妈妈，第二个标签是拆书练级者，第三个标签是一位在找工作的中年少女。今天我给大家带来的图书是《聪明人用方格笔记本》。\u003c/p>\u003cp>这本书的作者高桥政史， 曾经是日本麦肯锡咨询顾问。通过副标题《最有效的大脑思维整理术》看出来这是一本教读者通过记笔记整理大脑思维的书。通过学习使用方格笔记本可以帮助我们理清大脑思路，整理大脑内存，使工作、学习变得更加轻松、高效。\u003c/p>\u003cp>下面请大家用一分钟时间阅读原文片段，请阅读完毕的小伙伴抬头示意一下。\u003c/p>","ratings_count":1,"texts":[{"id":9639,"quote":"\u003cp>【阅读原书拆页】1分钟\u003c/p>\u003cp>1-2要求:能够选出带有具体行动指导的拆书拆页。\u003c/p>\u003cp>P35\u003c/p>\u003cp>黄金三分法之四】麦肯锡公司的“空・雨・伞”\u003c/p>\u003cp>麦肯锡公司的咨询顾问们都会使用一个框架，这个框架就是“空·雨·伞”。\u003c/p>\u003cp>正如《从麦肯锡到企业家》（东洋经济新报社）一书的作者、 Locondo公司总经理田中裕辅所说的那样，“在麦肯锡，所有思考都需严格按照“空·雨·伞＇三步执行”。\u003c/p>\u003cp>所谓“空·雨·伞”，其实就是判断何为“空＝现在的情况”，何为“雨＝对此情况的解释”，何为“伞＝根据此解释而采取的行动。\u003c/p>\u003cp>首先，抬头看天，发现天空中的云朵有些异样，解为好像要下雨了”。根据这一解释，判断应该采取“帯伞出门”的行动。\u003c/p>\u003cp>这就是“空·雨·伞”。\u003c/p>\u003cp>看到这里，你可能会说：“什么？这也太简单了！”可是，正是因为大家都觉得这是“再简单不过的事情”，所以未能付诸实践。\u003c/p>\u003cp>“简单就是终极的复杂。”\u003c/p>\u003cp>这是达・芬奇的一句名言。\u003c/p>\u003cp>“空・雨·伞”这一思考方式（框架）的本质正是麦肯锡的咨询顾问们努力掌握的至简至极的思法。\u003c/p>","explains":"\u003cp>【分享I便签】3分钟\u003c/p>\u003cp>1-2要求:讲解原文知识点，举一两个恰当的例子。\u003c/p>\u003cp>大家都差不多看完了。我看现场好多小伙伴都带了笔记本，请大家随着我的讲解翻看一下前面的笔记本。我们大家都从小就记笔记，上学时记板书，上班后做会议记录，那么我们会记笔记么？对自己记的笔记大家都满意么？会回头去翻看么？大家是不是有点这样的困扰？（在提问时做稍微的停顿）那么我今天将会向大家推荐一下麦肯锡非常经典的一个笔记框架，叫做“空雨伞” 。空是抬头看天空，就是忠实的记录，比如，看书是原文信息，会议是会议内容。雨是你看天空的时候的理解是晴空万里还是乌云密布，是你对记录下来的信息的解释，比如what、why、how的提问。最后什么是伞？就是你对解释判断出来的总结或行动计划，根据你的判断你要不要带伞出门？\u003c/p>\u003cp>我今天也拿一个笔记本，这是我学习空雨伞结构前的记笔记的习惯，大家可以看看，都是照抄板书或讲话的笔记本，现在看根本不记得当时为什么记录下这些内容？这本是我现在正在使用的方格笔记本，虽然字迹潦草，但我打开一看就知道有什么用。（用笔记本呈现），请大家看一下，这页记录了我刚才听彭亮拆解1-2使用使用“空雨伞”的结构做的笔记。\u003c/p>\u003cp>1.首先我用的是A4大小的方格本，横向放置，横竖画两条线，分为三个区域。\u003c/p>\u003cp>2.左边是记录，就是“空”，记录主讲人讲述的知识点。记录了结构性思维的上下对应原则。\u003c/p>\u003cp>3.右边是解释，就是“雨”，记录我对这些知识的理解或疑问。我认为上下对应原则是一种因果关系需要保持前后一致。\u003c/p>\u003cp>4.上面是行动计划和总结，就是“伞”。是我具体要去实践的行动计划。我今后要检查说话、写作是不是存在因果关系。\u003c/p>\u003cp>以上我讲解的是麦肯锡的“空雨伞”，它是“黄金三分法”记笔记的其中的一种结构。“黄金三分法”就是通过构建笔记框架的方式重新构建一种思考方式，将信息、知识有序整理，重点强调经过深度思考的解释和行动，培养逻辑思维习惯，使大脑通过刻意练习具有逻辑思维能力。\u003c/p>","interaction":"\u003cp>【激活A1便签】5分钟\u003c/p>\u003cp>1-2要求:能够激活学习者在小组内分享各自的【A1】经验。\u003c/p>\u003cp>听完了我的讲解，想请大家回忆一下：你们在过去一个月内参加会议或培训的时候，都是怎么做笔记的？大家是否有过思路不清晰，回过头来看自己也不知道记了什么的情况？请每个人在小组内分享自己是如何做笔记的，3分钟后，我会邀请1-2位小伙伴分享。\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>学习者：李胜华\u003c/p>\u003cp>我是一个比较喜欢记笔记的人，可以看看我前面记了很多笔记，有我们经理开会时记录的，有我自己做市场考察时记录的，现在看，真的不知道当时记下来有什么作用？\u003c/p>\u003cp>【催化应用A2便签】3分钟\u003c/p>\u003cp>1-2要求:能够成功催化学习者规划自己的【A2】应用，写在各自的便签上。\u003c/p>\u003cp>我们拆书帮强调拆为己用，请大家根据今天我们学习的“空雨伞”，写一个在未来工作、学习中的应用。我举个例子：“接下来的一个月内，我来参加拆书活动，会用空雨伞的格式在A4纸上做一次记录，或者参加公司会议用这个格式去做笔记”。一会儿我邀请一位伙伴分享一下。\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>学习者：康康\u003c/p>\u003cp>我根据丹燕分享的空雨伞的格式，我下周有一个优势才干培训课，我将纸横向使用，画两条线给它分成三部分，左边写下老师的培训内容，右边写我自己的理解，上面写根据内容和理解我下一步的行动方案，比如，我会使用这个所学的优势才干内容和别人进行沟通交流。\u003c/p>\u003cp>【小结】\u003c/p>\u003cp>感谢大家的分享，今天我的拆解就到此结束了，总结一下：就是通过画线分区，在记录的基础上、积极思考做出解释和行动计划，这样记录能让我们的学习更高效，从而快速提升能力、解决问题。希望今天的“空、雨、伞”能给大家的工作、生活带来帮助，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1540779866000,"updated_at":1540781194000,"ria":true},{"id":6161,"topic":"用黄金三分法高效做笔记、快速理清思路","learn_goal":"学习者，使用学会使用黄金三分法做学习笔记","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"洪传霖","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"大家好，我是洪传霖，今天很高兴能有机会在这里和大家一起分享这本《聪明人用方格笔记本进阶图解》。大家离得比较远，可能看不清楚它有一个副标题：“高效工作、学习的思维整理术”，做笔记跟我们做思维整理有什么关系呢？这就要用到书里提到的核心的方法：黄金三分法。黄金三分法是我们今天的主题，接下来，就请大家阅读以下刚发给大家的拆页片段，大概需要两分钟左右的时间，读完的小伙伴可以举手或者点头示意我一下，谢谢。","ratings_count":1,"texts":[{"id":9429,"quote":"\u003cp>精英们坚持实践的黄金三分法\u003c/p>\u003cp>选自《聪明人用方格笔记本进阶图解》【日】（高桥政史）P22，预计阅读时间1-2分钟。\u003c/p>\u003cp>【R-阅读原书拆页】\u003c/p>\u003cp>对信息的理解速度、学习和工作的效率会随着笔记本的使用方向而改变。“横向”使用方格笔记本的话，视野会变得开阔，而且能够快速把握整体情况。\u003c/p>\u003cp>笔记本的使用方向会影响信息的理解速度\u003c/p>\u003cp>东大录取生、全美知名大学以及科研机构的研究学者、外资公司的咨询顾问常按三分法(“黄金三分法”的简称)使用方格笔记本。让我们一起看一看“黄金三分法”的基本原则吧！\u003c/p>\u003cp>东大录取生的笔记本、全美知名大学以及科研机构的研究学者使用的“康奈尔笔记本”、麦肯锡公司使用的“麦肯锡笔记本”以及同样为外资咨询公司的埃森哲公司的“&quot; Point seat(点位控制笔记本)”等。这些笔记本都有一个共同的框架——“黄金三分法”。\u003c/p>\u003cp>大多数东大录取生的笔记本都是将左右两页并作一页使用的。左侧一页用来记录老师的板书，右侧一页的左半部分用来记录老师的评语和自己的疑问、发现，右半部分则用来写解决这些问题应该采取的行动以及概括总结。\u003c/p>\u003cp>全美首屈一指的名牌学府康奈尔大学心理学系研发的“康奈尔笔记本”是先将笔记本分为三部分，分别为记录板书的部分、其左侧的思考部分以及下方的归纳总结部分。\u003c/p>\u003cp>此笔记本的构造便于使用者养成按“板书”→“发现”→“总结”的顺序记笔记的习惯。\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴已经读完了，没读完的也没有关系，可以跟着我的讲解一起看看到底什么是黄金三分法，还有具体如何应用到学习和工作中。\u003c/p>\u003cp>这个片段讲的是黄金三分法的结构和做笔记的步骤，我们可以看到最下面的两张图，它们基本的结构包含三部分：板书、发现、总结。黄金三分法的原理就是通过分区让笔记的结构变得清晰明了，在记录的基础上，重点强调了经过深度思考的发现和总结的部分。\u003c/p>\u003cp>对照拆书帮的RIA便签学习法，我把黄金三分法在学习笔记场景中的应用概括为RIA三分笔记法，大家看一下后面的这个模版。\u003c/p>\u003cp>R是Record记录，记录我们观察到的事实，I是Interpretation诠释，写下我们提问的what、why、how，而总结的部分我们用A，Action来表示行动计划和总结。具体做笔记的步骤我将结合我自己做的笔记来做说明：\u003c/p>\u003cp>我的左手边是1-1定级时做的笔记，一眼看过完全抓不到重点，右手边是我回去学习了黄金三分法以后整理的笔记，大家可以对比一下，清晰地区分了记录、诠释和行动计划，I的部分我问了自己三个问题：What哪里做得不好，why为什么做得不好，how如何做得更好呢。有了反思追问和行动计划，大家给的营养丰富的洋葱苹果才能更好地消化吸收、学以致用。三分法做笔记的步骤是这样的：\u003c/p>\u003cp>1.首先拿一张A4纸（最好是方格纸能够方便对齐和画简单的图表），横向放置，画三条线，分为四个区域，这里需要强调一下，分区的方式根据不同的场景和需要突出的重点有很多种变体，我们今天只选最常见的三等分来举例。\u003c/p>\u003cp>2.最上面的部分写上日期和标题，比如2018年9月16号，TF1-1定级复盘与行动计划\u003c/p>\u003cp>3.左边的区域记录我们观察到的事实，比如我讲了什么内容、现场表达怎么样\u003c/p>\u003cp>4.中间的区域写下我们的理解诠释，比如what、why、how的提问\u003c/p>\u003cp>5.最右边的部分写我们的行动计划和总结，比如接下去针对演讲能力提升方面的刻意练习具体计划\u003c/p>\u003cp>总结一下：通过画线分区、写日期标题、在记录的基础上、积极思考做好诠释和行动计划，能让我们的学习更高效，从而快速提升能力、解决问题。\u003c/p>","interaction":"\u003cp>【A1激活经验】\u003c/p>\u003cp>相信小伙伴们对三分法做笔记有了一定的了解，接下来我们准备进行分组讨论，从这边开始两个人为一组。请每个人结合自己现在做笔记的方法或者以往学习过程中做笔记的经验，在小组内分享自己是如何做笔记的，是否有标题、进一步诠释以及行动计划和总结等，3-5分钟后，我们会邀请1-2位小伙伴分享。微信群里也可以看到讨论的参考问题。\u003c/p>\u003cp>大家可以两两为一组，最后这组多了一位可以三位小伙伴为一组。\u003cbr>\u003c/p>\u003cp>（讨论4min）\u003cbr>\u003c/p>\u003cp>【A1分享】\u003c/p>\u003cp>好的，我看大家可能讨论得差不多了，如果有更多需要讨论的我们可以在活动之后在微信群里做进一步交流。接下来，有没有小伙伴想先上来分享一下自己做笔记的经验呢？我看一下谁笔记做得比较认真。\u003c/p>\u003cp>丽丽：我分享一下吧，刚才有说到几个点：第一个点尺寸，像我如果在外面的话，一般会用A5尺寸的笔记本，比较便携，如果在公司正常用A4的笔记本。分区和消化，分区一般没有做，但是例如做会议纪要的时候，肯定会做分区，会议结束之后也会有整理，如果是会议笔记一般会有行动，但是普通的笔记比较少有行动计划。重要的关键词一般都会标出来，这样比较清晰。\u003c/p>\u003cp>好的，谢谢丽丽的分享，确实跟丽丽说的一样，三分法其实不只像我刚才举例的三等分，像刚才丽丽提到的会议纪要啊等等不同的场景有非常多的变体，拆页后面有二维码，我们可以看到24种不同的模板，都是黄金三分法的不同模板，大家可以参考其中的模板应用到实际的学习和工作中。再次感谢丽丽的分享。\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>在拆书帮，我们强调拆为己用，请大家根据今天我们学习的黄金三分法，在发给大家的小便签上，写下自己的行动计划。行动计划最好有包含时间、具体的数量和应用场景等等。我举个例子：“接下来的一个月内，我要用黄金三分法在A4纸上做一次定级观摩笔记和两篇微课学习笔记”。注意要包含时间范围和具体的数量，大家便签写好以后可以把便签给我。\u003c/p>\u003cp>我们今天的定级分享就到这里，感谢大家的积极参与，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1538204519000,"updated_at":1538204519000,"ria":true},{"id":5945,"topic":"运用黄金三分法，构建知识框架","learn_goal":"学会黄金三分法的其中一个框架，用简单的框架升级你的笔记术","remark":"《聪明人用方格笔记本》这本书的作者是高桥政史，他开创了一种笔记记录法。通过这种方法记笔记，能提高记笔记时的效率，并使信息结构化。\r\n这是一本教读者通过记笔记整理大脑思路的书。这本书运用简单的文字和图片，清楚地告诉读者如何改进记笔记的方法","level":"TF1-2","duration":90,"status":0,"type":0,"chaishujia":{"username":"碧兰","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家晚上好，我是今晚线上活动的拆书家碧兰。觉得我的声音可以听清的小伙伴请打个1\r\n首先我来介绍今晚的\r\n线上拆书流程：\r\n【拆书&amp;拆书帮介绍】\r\n【拆书家介绍】\r\n【图书介绍】\r\n【拆页拆解】\r\n【总结】\r\n &nbsp;\u003c/p>\u003cp>【拆书介绍】拆书是一种学习方法，「拆」=「拆为己用」，不是简单的拆解，而是聚焦于知识点，不是说把书看完就行了，而是要把书中的知识转化为自己的能力。&nbsp;\u003c/p>\u003cp>【RIA拆书法介绍】：拆书帮学习方法论的核心，可以一个人读书学习时自用，也可以由拆书家带领一群人（即学习者）一起用。\u003c/p>\u003cp>RIA分别指的是：\u003c/p>\u003cp>R（Reading）：阅读原文片段。\u003c/p>\u003cp>I（Interpretation）：拆书家进行讲解引导。\u003c/p>\u003cp>A（Application）：学习者拆为己用，实践与行动。\u003c/p>\u003cp>A又分为A1、A2\u003c/p>\u003cp>A1：指向过去&amp;激活学习者的过去的相关经验。\u003c/p>\u003cp>A2：指向未来&amp;催化学习者规划以后怎么应用、如何具体行动。\u003c/p>\u003cp>【拆书帮】：\u003c/p>\u003cp>拆书帮是基于拆书方法的学习爱好者社群，在全国各地都有分舵。每个分舵都是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>【拆书帮的基本理念】:\u003c/p>\u003cp>拆书帮的基本理念有三点\u003c/p>\u003cp>首先，你不必读完全书，更不必担心记不住，能用上一点就值回百倍书价\u003c/p>\u003cp>第二，读任何一本30块钱的致用类图书，完全能达到参加3万块钱培训的效果\u003c/p>\u003cp>最后，凡是不联系经验的学习都不配称为成人学习，凡是不改变行为的学习都是极大的浪费 \u003c/p>\u003cp>今晚，就是由我来带领大家一起拆书。即便是第一次参加拆书的小伙伴，也不必担心。请大家跟着我的节奏，尽情发言就好啦。下面，我会做一个简单的自我介绍，然后便一起进入今天的拆书主题。\u003c/p>\u003cp>【拆书家介绍】\u003c/p>\u003cp>我叫碧兰，是广州小蛮腰分舵的一名一级拆书家。我现在韩国留学。我的爱好是演讲和读书，也一直有参与头马演讲俱乐部的运营工作。我的愿望是拆书帮能走出国门，走向世界。\u003cbr>\u003c/p>\u003cp>【书籍介绍】&nbsp;+ 图片（图书）\u003cbr> 《聪明人用方格笔记本》这本书的作者是高桥政史，他开创了一种笔记记录法。通过这种方法记笔记，能提高记笔记时的效率，并使信息结构化。\u003c/p>\u003cp>这是一本教读者通过记笔记整理大脑思路的书。这本书运用简单的文字和图片，清楚地告诉读者如何改进记笔记的方法\u003c/p>\u003cp>大家有没有因为密密麻麻无空隙的笔记而烦恼呢？有没有因为记笔记的速度跟不上老师或者是会议的速度而错过了重点内容？这本书可以让你学会如何高效地，有结构地记笔记并理清思路。\u003c/p>\u003cp>我们今天会拆解三个片段，主题是关于“运用黄金三分法，构建信息框架”。希望今天的学习能让大家可以掌握黄金三分法的结构特点，并能够正确运用到学习和工作上。\u003c/p>","ratings_count":0,"texts":[{"id":9166,"quote":"\u003cp>存在漏洞的英语学习=阻碍能力发挥的笔记本\u003c/p>\u003cp>“到在才换笔记本，应该不会有多大的变化把？”\u003c/p>\u003cp>也许有人会这么想。\u003c/p>\u003cp>可是，笔记本是我们每天都要用到的东西，就像每日饮食能够影响到人体健康一样。如果你继续按照老方法记笔记的话，那么它将在未来的很长一段时间内对你产生负面的影响。\u003c/p>\u003cp>比如，有很多人明明从初中就开始学习英语，一直学到大学，学了十年，却发现自己的英语水平达不到工作要求。\u003c/p>\u003cp>这是为什么呢？\u003c/p>\u003cp>因为大多数人的英语学习方法存在很大的漏洞。\u003c/p>\u003cp>这和“阻碍能力发挥的笔记本”的问题是同样的。\u003c/p>\u003cp>多数人记笔记的技巧停留在学生水平，甚至都不会去想这样下去会怎样，而且将其变为了一种习惯。\u003c/p>\u003cp>这种习惯持续下去的话，不但会影响能力的全方位发展，还会持续阻碍能力的发挥，甚至造成能力的下降。\u003c/p>\u003cp>如果你继续按照错误的方法记笔记的话，那么，你的动脑能力也在慢慢减弱，学习到的知识、技巧、经验，以及花费在这些学习上的时间都将付诸东流。\u003c/p>\u003cp>不仅如此，如果你继续这样记笔记的话，你还将失去未来人生路上的各种机遇，使你的人生前功尽弃。\u003c/p>\u003cp>重新审视自己的笔记本，立刻将阻碍“能力发挥的笔记本”变为“使头脑变聪明的笔记本”的最重要原因就在于此。\u003c/p>","explains":"\u003cp>如果我们去问一个人，你会不会做笔记，我相信大部分人都会回答：我会。记笔记听起来是一件非常简单的事情。很多人会这样想：笔记嘛，多简单，学生时期，就抄板书，老师说什么我记什么。在工作中也很简单啊，老板说什么我记什么。但是，这样真的会给我们的生活带来便利吗？\u003c/p>\u003cp>其实不然。盲目的复制粘贴，容易令我们失去独立思考的能力。我们的学习方法，都是随着知识和能力的增长不断在改进。就像从学生时期的死记硬背，向我们拆书帮提倡的成人学习法转变一样，记笔记的方法也需要进行升级。\u003c/p>","interaction":"\u003cp>我先给大家举个例子。我以前也是很喜欢把老师写在黑板的板书一模一样的记下来。看起来是“认真听课”，但是其实下课后根本想不起来自己到底学到了什么。而且我还喜欢用各种荧光笔“标重点”。但是其实重点是标了，有时候哪个颜色代表什么，就很容易搞混。\u003c/p>\u003cp>现在，我请大家回忆一下：自己平时有哪些记笔记的习惯？或者是用什么方法记笔记的？在我发的图片中，选出下列符合自己的笔记本类型。这些习惯或者是方法给你的学习，工作和生活带来了什么不好影响？\u003c/p>\u003cp>格式：\u003c/p>\u003cp>我的习惯是….对应笔记本类型…..。给我带来的影响是…..\u003c/p>\u003cp>请大家一次分享完，分享完毕后用ok结束。影响就是重点不突出，很多事情一起来时，没法抓住主次；另外就是不想回顾看笔记，有技术点的笔记内容不久就忘记了。OK\u003c/p>\u003cp>参与者jackson：我的习惯流水账.对应笔记本类型2-4-7-8。给我带来的影响是…..\u003c/p>\u003cp>请大家一次分享完，分享完毕后用ok结束\u003c/p>\u003cp>参与者高宏琳：我的习惯是能记多少记多少，对应笔记本类型1-4-8。给我带来的影响是不太想看，也记不住\u003c/p>\u003cp>参与者3：类型属于2-7这种。格式是，1书名+作者+摘文段（p页数）&nbsp;&nbsp;&nbsp; 2书名+作者+摘文段（p页数）+感想&nbsp;&nbsp;&nbsp;&nbsp; 3书名+作者+简短字句摘录。感想:单本书籍一目了然，但多本书在一起就不容易书籍内容查找\u003c/p>\u003cp>分享完的小伙伴们，可以对照第二张图，看自己的哪些能力需要提高。请写出自己需要提高的能力。请一次回答完，回答完毕后用ok结束。\u003c/p>\u003cp>参与者jackson：逻辑思维能力，整理能力，视觉能力，学习能力\u003c/p>\u003cp>参与者：我一般不记笔记，因此我所有能力都待提高，完毕\u003c/p>\u003cp>参与者3：理解能力、学习能力、整理能力有待提高\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":9167,"quote":"\u003cp>“框架”决定学习和工作的品质\u003c/p>\u003cp>就像道路中心线有助于汽车顺利行驶一样，合理的框架也有助于学习、研究、工作的顺利开展。正是因为有了框架，我们才得以按照目标整理和梳理知识、信息，取得理想的效果。\u003c/p>\u003cp>能否使头脑变聪明？\u003c/p>\u003cp>起决定性作用的是“框架”。\u003c/p>\u003cp>工作中的“框架”也可以称为“格式”。\u003c/p>\u003cp>先决定好格式，然后将信息和想法按照格式进行排列、整理、归纳。这样一来就可以快速高效地制定出一套高品质的企划方案或演示文稿。\u003c/p>\u003cp>很多人不注重格式，但事实上正因为有了格式，我们才能将所需的信息提炼出要点，进行有效的整理。\u003c/p>\u003cp>不单单是在工作、学习领域，就连在体育等领域也是一样，一流运动选手若想取得理想的成绩，也需将“框架”贯彻到底。\u003c/p>\u003cp>外资管理咨询公司也有优秀的框架。\u003c/p>\u003cp>“框架决定工作和学习的品质”\u003c/p>\u003cp>在和他们沟通的过程中，我注意到了这一点。\u003c/p>\u003cp>所用的框架不同，结构也会不同。\u003c/p>\u003cp>所有人都可以将外资咨询顾问们的框架化为己用，这个框架就是方格笔记本。\u003c/p>\u003cp>就像道路中心线一样，将方格笔记本中的横线、竖线作为指引线思考整理问题的话，工作和学习将取得意想不到的成果。\u003c/p>\u003cp>那么，就让我们赶快探究一下，外资管理顾问们爱用的方格笔记本中隐藏的秘密吧！\u003c/p>","explains":"\u003cp>提升记笔记方法的第一步是构建框架。框架就像盖房子中最重要的地基。在有坚固的地基的前提下，楼房才能盖的高和漂亮。笔记有了好的框架，我们就可以高效地对我们接受的信息进行过滤，整理和归纳。方格笔记本中的方格就给我们很好的框架。但是光有方格，不提升记笔记的技巧的话，还是一样没有改变。所以我们在接下来在片段3中会学习黄金三分法中的其中一个用法，埃森哲公司所使用的point sheet.\u003c/p>","interaction":null,"flags":{"r":true,"i":true,"a":false,"a1":false,"a2":false,"a3":false}},{"id":9168,"quote":"\u003cp>【黄金三分法之三】埃森哲公司的“Point Sheet”\u003c/p>\u003cp>全球之大的外资管理公司埃森哲使用的是一种名为“Point Sheet”的格式。\u003c/p>\u003cp>格式中的横线和竖线都是浅绿色的，表格部分上由上面的“题目“、左侧的”重点“、右侧的”行动“三部分组成。\u003c/p>\u003cp>左侧的部分用来记录重点，右侧的部分则用来书写基于重点应采取的行动。即“谁，在什么时间之前，要做完什么事“。\u003c/p>\u003cp>因为“重点à行动”的顺序可以按照由左到右的顺序自然得到书写整理，所以，”为何要采取这样的行动“，任何人看了都能一目了然，马上就能采取相应的行动。\u003c/p>","explains":"\u003cp>这个片段很短，但是非常简洁地说明了Point Sheet的使用方法。记录被分为三个部分，最上面写标题、题目。一份笔记或者是记录有明确的项目或者是行动名称的话，不但可以给自己反复翻阅提供便利，而且就算要呈现给他人看也是非常清晰明了的。\u003c/p>\u003cp>题目下方的左侧用于记录重点内容及提炼出来的关键信息。尽可能简洁，为下一个步骤，行动计划的整理提供便利。\u003c/p>\u003cp>最后一步，完成右侧“行动”板块的书写。基于重点部分的内容整理出——谁在什么时间之前要做什么事。下面给出的图片是三分法的样式，以及适用范围。这个类型的笔记多用于行动计划的书写以及团队项目中的记录和分工。\u003c/p>","interaction":"\u003cp>下面请大家用5分钟的时间，运用三分法去修改自己以前做的笔记或者是记录。请完成的小伙伴们把自己的练习拍张照片，并分享到群里。（可以是两份笔记的对比图，也可以是一张修改好的笔记）\u003c/p>\u003cp>参与者\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1535551589000,"updated_at":1535551732000,"ria":true},{"id":5588,"topic":"笔记法","learn_goal":"学会用“黄金三分”框架笔记法锤炼思维、提升能力、提高效率。","remark":"","level":"TF1-2","duration":16,"status":30,"type":0,"chaishujia":{"username":"陈静","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍及图书介绍】\r\n大家晚上好，我叫陈静，首先用三个标签来介绍一下自己，第一个标签，开福区政协委员；第二个标签，我是一家工程、财务咨询公司的营销中层管理人员；第三个标签，一位希望以终身学习的践行影响与陪伴孩子共同成长的妈妈。\r\n今天我拆的书是《聪明人用方格笔记本》，这是一本思维训练书，帮助我们通过使用方格笔记本理清大脑思路，整理大脑内存，使学习、工作变得更加轻松、高效！\r\n下面请大家先阅读手中的片段，时间大约1分钟，阅读完以后，请大家抬头示意我一下就可以了。","ratings_count":1,"texts":[{"id":8767,"quote":"\u003cp>&nbsp; &nbsp; 摘自《聪明人用方格笔记本》P31\u003c/p>","explains":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>拆书家讲解引导】\u003c/strong>\u003c/p>\u003cp>我看到大多数的小伙伴都已经阅读完毕了，我理解的 “黄金三分法” 框架笔记，是通过构建一种思考方式，将信息、知识有序整理，从而培养逻辑思维习惯，提高逻辑思维能力，使大脑经过刻意训练以后变得越来越聪明，达到高效学习、高效工作、提升能力的目的。\u003c/p>\u003cp>俗话说：“好记心不如烂笔头”， 笔记是我们生活中重要的学习手段。我看到现场的小伙伴也准备了笔记本，不光我们自己，有孩子的爸爸妈妈也会经常提醒孩子们在上课记得做笔记！\u003c/p>\u003cp>按照“用进废退”的观点，不良的笔记习惯可能使你的大脑因为缺乏锻炼而慢慢丧失思考能力，好的笔记是锤炼思维、提升能力的工具。\u003c/p>\u003cp>回想，我平时在会议中做笔记的习惯是把主讲人的讲话一大点一小点记下来，零零散散，过后再看根本回忆不起来前因后果，不知道为什么要记这些内容；在学习培训课中则习惯记下自己比较喜欢的观点，或者老师说到重要的内容，再翻看时，也不知道还能用到哪些地方，失去了记录的价值。\u003c/p>\u003cp>下面，我们一起来改变笔记习惯，学习这种使头脑变聪明的 “黄金三分”框架笔记法，这个框架按照“记事实、作解释、拟行动”三步走，使用时有一个前题是，需要把笔记本左右两页作为一个版面，再一一按照这三个步骤记录：\u003c/p>\u003cp>第一步，记事实。也就是实事求是的记录下会议中主讲的内容，或者是学习培训中的课堂内容。\u003c/p>\u003cp>第二步，作解释。针对第一点的事实分别作出的解释、补充或者思考、疑问等信息。\u003c/p>\u003cp>第三步，拟行动。针对前两点对应作出的行动措施或者总结意见。为了更好的理解如何操作，我以今天现场拆书学习为例，请大\u003c/p>\u003cp>家看一下（有笔记本作呈现），左边“板书=事实”这部分记录我主讲人讲的学习内容，“发现点=解释”记录下一步观察家对我的点评、大家对我的建议、自己产生的疑问、思考等；“行动=总结”也就是我们针对左、中两点对应作出的总结或者行动措施。\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>激活学习者经验】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家设计提问】\u003c/strong>\u003c/p>\u003cp>我想请在座的每一位回忆一下：\u003c/p>\u003cp>你们在参加会议或者参加培训学习的时候，是怎么做笔记的？过后再来看自己的笔记时，有没有出现思路不清晰，或者连自己都不知道有什么用？是不是感觉对工作、学习也没有多大的帮助？大家有没有过这们的经验或者问题呢？\u003c/p>\u003cp>接下来请每一位想一个发生在自己身上记笔记的实例，并在各组讨论。\u003c/p>\u003cp>\u003cstrong>【分\u003c/strong>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>组】\u003c/strong>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>\u003c/p>\u003cp>我先给大家分下组，每2位小伙伴为一组。讨论完以后，我将请一位小伙伴，来跟我们分享他的经验。\u003c/p>\u003cp>\u003cstrong>【讨\u003c/strong>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>论】\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【伙伴分享】\u003c/strong>\u003c/p>\u003cp>我读高中的时候是一个笔记本狂热爱好者,经常看到好看的笔记本就会购买下来,计划是做语文、英语、数学等课程笔记，但是最后并没有按照计划来，反而浪费了很多本子；工作之后，每次做会议纪要，虽然能够按照领导的思路把内容给记录下来，但是整体还是凌乱的，如果领导现场回顾问题，也有答不出的情况,会后还需要花时间二次整理。\u003c/p>\u003cp>感谢文杏的分享！看来作为一个笔记达人都会记下零乱的笔记，不良的笔记习惯确实给大家带来了很多困扰与问题。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>邀请学习者写便签】\u003c/strong>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>最好的学习是学以致用。\u003c/p>\u003cp>下面，请大家按照今天所学的内容，写一个未来工作或学习中的具体运用。也就是说在未来的一周中，大家如何运用 “黄金三分”框架笔记，在工作中或者是学习中去具体运用呢？比如在未来一周的公司月度会中，比如培训课上，你将怎么运用？\u003c/p>\u003cp>\u003cstrong>提示：\u003c/strong>为了更加清晰，我给大家一个模版，在生活中运用时需要具体到模版上的几个内容，写完以后我请一位小伙伴分享：\u003c/p>\u003cp>便签模版：【时&nbsp;&nbsp;&nbsp; 间】：\u003c/p>\u003cp>【场 &nbsp;&nbsp;&nbsp;景】：\u003c/p>\u003cp>【人&nbsp;&nbsp;&nbsp; 物】：\u003c/p>\u003cp>【具体做法】：\u003c/p>\u003cp>【达到效果】：\u003c/p>\u003cp>\u003cstrong>【伙伴分享】\u003c/strong>\u003c/p>\u003cp>这个周末，在家里看书的时候，我将用“黄金三分”框架笔记法用到阅读的读书笔记上，具体做法是在“板书”部分摘抄书中的段落或者句子，“解释”部分我将写下对摘抄原文自己的理解， “总结”部分写下这些金句可以应用到生活、工作中的哪些地方，希望达到的效果是，加深对书的理解。\u003c/p>\u003cp>感谢肖雄的分享，让我们又找到更多的应用点！\u003c/p>\u003cp>谢谢大家，今天我的拆解到这里就结束了，希望我的拆解给大家的工作与学习带来帮助！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1532529509000,"updated_at":1532529509000,"ria":true},{"id":4962,"topic":"用三分法结构笔记助力学习与思考。","learn_goal":"使用三分法结构笔记，记录学习听课内容，建立基于事实的思考框架","remark":"","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"李喂喂喂喂","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】大家好，我是李炜，木子李，火字旁的炜。自从加入拆书帮，我除了成长为了一名正在过级打怪的拆书家，也成为了一名中级生涯规划师、野生摄影师和长沙有书同城的线下活动的组织者。【介绍《聪明人用方格笔记本》】\r\n【事件】大家从小到大，尤其是在学校读书时，是不是总是离不开记录各种学习笔记，包括现在进入职场，来到我们拆书帮也不免要用笔记本记录下所学所思。\r\n【提问】那问下在坐的各位，你记录下的学习笔记都能很好的帮助你内化为自己的知识和能力了么？\r\n【影响】一份优质的学习笔记总能节约我们的时间，提升我们的学习效率，让我们更高效的吸收知识，如果你做的学习笔记，不能助你立马回顾所学知识，让你更好的消化理解所学，不仅对你来说没有益处，甚至可以把这些笔记看成一堆占了空间又没有实际用处的废纸。\r\n【解决】而今天为大家带来的这本《聪明人用方格笔记本》是一本教读者如何通过记笔记整理大脑思路的书，它能让你通过正确的记笔记，达到高效学习，快速回顾，学以致用的效果，同时也能为你整理杂乱的信息，辅助你抓住问题的本质进行信息梳理与思考，解决职场与生活难题。","ratings_count":2,"texts":[{"id":8050,"quote":"\u003cp>【R: 阅读原文案例】\u003c/p>\u003cp>A4大小的笔记本可横向使用单页，B5大小的笔记本可以将左右两页作为一页使用，这样可以使视野变得开阔。在左侧记录事实、板书，然后一次往右书写解释、做法（结论）。总而言之，就是按照基于“左侧”的事实在“右侧”展开思考的流程书写。\u003c/p>","explains":"\u003cp>\u003cstrong>【 学习目标 】 \u003c/strong>【 可观察到的动作 】，【具体内容 】，【 完成程度 】\u003c/p>\u003cp>希望各位通过此次RIA现场学习，能够在今后阅读书籍或写听课笔记时，用上“三分法”结构笔记，完成高效记录，并能结合自身思考消化所学知识。\u003c/p>\u003cp>\u003cstrong>【互动】\u003c/strong>\u003c/p>\u003cp>拆书家：大家看完片段可以看到三分法总共有几个区域呢？\u003c/p>\u003cp>爱好者：四个\u003c/p>\u003cp>拆书家：分别是哪四个？\u003c/p>\u003cp>爱好者：标题区、事实区、解释区和做法区。\u003c/p>\u003cp>\u003cstrong>【步骤how】\u003c/strong>\u003c/p>\u003cp>拆书家；那我们看完原文片段是不是能很清晰的了解三分法结构笔记的一个基本组成框架了？使用它也只需要简单的五个步骤。\u003c/p>\u003cp>第一：在笔记本上建立三分结构。\u003c/p>\u003cp>用一条横线三条竖线画出这四个区域。\u003c/p>\u003cp>第二：顶端标题区写下学习主题和时间\u003c/p>\u003cp>如“3月29日学习整理法”“如何30分钟读完一本书 2018-3-29”\u003c/p>\u003cp>第三：在“事实区”也是笔记本的最左边，写下阅读学习或者听课中的笔记或老师的板书。\u003c/p>\u003cp>第四：在“解释区”，写下自己的理解和思考，\u003c/p>\u003cp>注意，这部分才是“三分法结构笔记”的重点，你在课堂上有自己的理解和思考就可以立马写下来，当时没有想法的话，可以留着课后复习时再来写，这个笔记区域是用来消化所学知识做思考记录用的。\u003c/p>\u003cp>第五：在“做法区”写下你学习吸收后得出的结论，或是你下一步的行动计划。\u003c/p>\u003cp>拆书帮的小伙伴听起来有没有很熟悉的感觉，这个“三分法结构笔记”是不是有点像我们的RIA便签读书法，R的原文片段变成了“事实区”的学习笔记和课堂板书， I的重述原文就是我们“解释区”的自我思考,最后A的行动建议则是我们“做法区”学习后的结论与行动方案。\u003c/p>\u003cp>\u003cstrong>【预防异议+讲解】\u003c/strong>\u003c/p>\u003cp>很多小伙伴可能会疑惑，这样换个方向，画几个区域记录下的笔记，就真能更好的吸收我们课堂学习的知识吗？我得说师傅领进门修行在个人，三分法结构笔记最重要的不是你记下了多少内容而是你在“事实区”写下的思考和“做法区”做出的结论和运用，有了思考和运用这样的消化和咀嚼的过程，自然比单纯的抄写笔记和板书要对知识点理解得更深入，吸收得更有效。\u003c/p>\u003cp>\u003cstrong>【明确适用边界】\u003c/strong>\u003c/p>\u003cp>不过“三分法”结构笔记在听课过程中比较适用于理论和经验性知识的学习和理解，对于技能性和操作性知识如学习制作幻灯片和PS修图还是有局限的，毕竟这类学习都以操作做主，熟悉才能生巧。\u003c/p>","interaction":"\u003cp>\u003cstrong>【引导学习者伙伴分享场景/需求】\u003c/strong>\u003c/p>\u003cp>请大家想一下，未来一周的生活或者工作中有能够用到“三分法”构笔记来进行学习和听课的场景吗？比如公司每周的培训会；或者最近打算在家阅读哪本书？准备报名参加什么培训和资格认证的学习等等。请大家想一想，会有遇到需要用上结构笔记记录分享的场景吗？是什么场景呢？给大家一分钟的时间互相讨论一些，待会请大家直接分享出来哦。\u003c/p>\u003cp>爱好者：我刚好这个周末要参加一次培训课程。\u003c/p>\u003cp>爱好者帆：我也是，下个月有场时间管理的培训。\u003c/p>\u003cp>\u003cstrong>【布置特定任务】\u003c/strong>\u003c/p>\u003cp>拆书家：感谢大家的分享，看来四月份适合精进学习的好时节啊！那为了更好地练习“三分法”结构笔记这种学习技巧，我来给大家布置一个作业，都说教会他人才是最好的学习，请大家在你未来要用上“三分法”结构笔记的场合下，如刚刚很多小伙伴都要参加培训，那请将你今天学习到的结构笔记的使用方法教给你的同学，使他们也能学会这样简单实用的笔记法如何？\u003c/p>\u003cp>现在，请你设想下你会怎样教她通过五个步骤使用“三分法结构笔记”呢？请花5分钟时间，写下来，待会找小伙伴分享下哦！\u003c/p>\u003cp>拆书家：哪位伙伴愿意分享下？\u003c/p>\u003cp>爱好者帆：我来吧，下个月的培训会，我会这样教我隔壁桌的同学使用“三分法结构笔记”做听课记录，第一步，我会教她用一横三竖画出这四个区域；第二步，教她写下标题和时间；第三步，教她在“事实区”写下听课记录；第四步，告诉她在“解释区”写下对“事实区”板书和笔记的思考；第五步，教她在“做法区”将自己的思考整理成一个结论或者实际的行动步骤。\u003c/p>\u003cp>【提问反馈 】\u003c/p>\u003cp>拆书家：非常棒的分享，大家听完后是不是能感受到以教为学就是一种很好的复习和检验所学知识的方法呢？\u003cbr>\u003c/p>\u003cp>爱好者：是的。\u003c/p>\u003cp>拆书家：我们通过帆的分享，是不是也能感受到她已经妥妥的知道如何使用“三分法结构笔记”了呢？\u003c/p>\u003cp>爱好者：是的，感觉很明显。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【结语及两个片段之间的联系】\u003c/strong>\u003c/p>\u003cp>我们通过简单学习和演练知道了如何用三分法结构笔记做听课记录，那你们知道如何用结构笔记思考问题吗？三分法结构笔记除了是我们学习的利器也是我们整理大脑，建立框架思维的好帮手。下一个片段的拆解后，我们会发现同一个结构笔记，不同的用法可以助你理清思路，通过层层追问找出问题本质，把解决方案整理出来。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":8051,"quote":"\u003cp>拆书家：拆解下一个片段前，请各位先完成以下自测量表，动动笔，为自己计个分数，1分代表不怎么符合，6分表示非常符合，请结合你的实际情况来给出分数哦！开始测试吧！\u003c/p>\u003cp>【自测量表】\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、我能基于事实情况思考问题。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、当我的朋友遇到问题，会向我咨询寻求帮助。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、在工作中，我会发现大家没有关注到的问题。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、当我遇到难题时，能够找到解决问题的关键。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、我能从很多信息中，找到对工作开展最有利的信息。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【自测表 - 量表解释 】\u003c/p>\u003cp>拆书家：不知大家的分数算出来没？现场有没有23分以上的？可以举手示意下吗？\u003c/p>\u003cp>爱好者：有（4人举手）\u003c/p>\u003cp>拆书家：你们肯定是善于思考问题的人，身边的朋友是不是都爱向你们请教呢？\u003c/p>\u003cp>拆书家：那有没有11分以下的呢？\u003c/p>\u003cp>拆书家：1人，如果在这个区间就证明你在解决问题方面可能还有点困难，还需要进一步学习提升哦。\u003c/p>\u003cp>拆书家：而剩下几位11-23分区间的小伙伴，就处于解决问题能力的平均值，能满足正常需求，也有一定的提升空间。\u003c/p>\u003cp>拆书家；那接下来让我们看到原文片段。\u003c/p>\u003cp>【R: 阅读原文片段2&nbsp; 不带HOW】\u003c/p>\u003cp>截止到目前为止，是否有人教过你要基于事实思考问题呢？\u003c/p>\u003cp>正如我前面提到过的那样，很少有人知道要“基于事实思考问题”如果事实与此相反，你早就知道这一点，并且早早养成了“基于事实思考问题”的习惯，那么，你将可以把竞争对手远远地甩在身后。\u003c/p>\u003cp>不仅如此，这一习惯将为你的一生带来积极的影响。\u003c/p>\u003cp>“基于事实思考问题”是一项强有力的武器。\u003c/p>\u003cp>读过前面几章，你应该已经知道要按照三分法使用方格笔记本了吧！用提案笔记本的左侧区域记录事实和用学习笔记本的左侧区域记录板书是一样的道理。因为老师写在黑板上的板书基本上都是“事实”比如历史、数学公式、文章、食物链图等等。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[\u003c/strong>\u003cstrong>学习目标】\u003c/strong>\u003c/p>\u003cp>阅读完原文片段二，希望大家通过接下来到RIA现场学习，在职场或工作中，如果面对信息杂乱难梳理的状况，能知道如何用三分法结构的五步骤，建立一个框架思维模式。\u003c/p>\u003cp>\u003cstrong>【互动】\u003c/strong>\u003c/p>\u003cp>拆书家：大家看到原文片段觉得它提出的重点是什么？\u003c/p>\u003cp>分享者：要基于事实思考问题。\u003c/p>\u003cp>\u003cstrong>【概念讲解】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>是的，在这里我们首先要理解什么是事实，如果不能区分出事实，就无法真正做到基于事实思考问题，即使有一个思考框架在，也无法正确使用它来梳理我们杂乱的信息。就像方向一开始是错的，一切都会徒劳。而\u003c/strong>我们要区分的事实也就是客观发生的事情，不以人物主观意向的不同而发生改变，是怎样就怎样，\u003cstrong>【举出案例】\u003c/strong>比如我是一个三岁孩子的妈妈，这就是一个事实，不管我装得再嫩，别人怎么说看不出来，我依旧是个三岁孩子的妈妈，这件事情已经发生，不可改变。\u003c/p>\u003cp>\u003cstrong>【类似概念】\u003c/strong>\u003c/p>\u003cp>那最容易和事实混淆的是什么？是观点，是一个人对于某个事实的主观判断，而且你很难评判对错，比如，\u003cstrong>【类似概念的例子】\u003c/strong>我说自己是一个贤惠的妈妈。贤惠这个词就是我对自己的主观判断，而在我婆婆眼里，我可未必贤惠。所以贤惠的妈妈，是一种主观判断，是一个观点，不是事实。\u003c/p>\u003cp>\u003cstrong>【步骤how】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>所以分清楚这两点，我们才能更好更高效的用三分法结构笔记来进行基于事实的问题思考。\u003c/strong>\u003c/p>\u003cp>我们可以看到之前用到的结构图。\u003c/p>\u003cp>第一步：画出三分结构区域。【给出图示辅助讲解】\u003c/p>\u003cp>第二步：在标题区，写上想要解决的问题。\u003c/p>\u003cp>比如我最近想解决的是：如何提高工作期间的办事效率，不被手机消息和临时任务影响？。\u003c/p>\u003cp>第三步：在现状处，先逐条列出目前的现状。用蓝色笔记划出事实，用来和观点做区分。\u003c/p>\u003cp>如我列出来以下几点状况，第一条工作期间时不时刷手机，被各种信息吸引也被各种信息干扰。然后找到事实“时不时刷手机”用蓝色标记。\u003c/p>\u003cp>第四步：在解释区写下，找到基于事实应该解决的问题并连问“为什么”深入剖析，挖掘出本质。\u003c/p>\u003cp>基于事实情况，我才发现自己的核心问题是有时间刷手机，却没有时间完成每天的工作。接着，追溯出第一原因是因为自己心态没有摆正，越来事越拖延。但这只是开始，然后再问自己为什么？再提炼出一个原因，比如我分析后，第二条写下的原因是因为前期工作存在拖延或敷衍对待，遇到紧急任务就容易情绪不好。还没结束再追问为什么会这样呢？第三次思考写下：因为平时一直在做紧急又重要的事，没有及早处理重要不紧急的事情。继续追问自己，为什么？第四次思考写下：平时工作习惯没养成，没有做到今日事今日毕。直到得出一个直击自己痛点的结论。要注意的是，同一个问题对不同的人答案未必相同，这毕竟都是基于自己实际情况还有理解和需求做出的解答。\u003c/p>\u003cp>第五步：在做法区写下对策，在“事实——解释”的基础上，明确的指出，现在应该由谁，毫不犹豫的采取怎样的行动。我最后给出的对策就是要做到今日事今日毕，每天写下今日待办清单，并为自己请一个监督员，未完成每日待办清单就给监督员发一个大红包，连续一周都完成了就给自己一个小奖励。\u003c/p>\u003cp>第六步：在标题区域问题的下方，写下问题结论。我写下了“总之，要养成今日事今日毕的习惯。”\u003c/p>\u003cp>\u003cstrong>【预防异议+讲解】\u003c/strong>\u003c/p>\u003cp>当然，你可能会疑惑，思考问题用得着弄得这么复杂吗？我只能说，这个“基于事实思考问题”的结构框架是用来帮助那些不太知道如何从大量事实与观点混淆的信息中，整理出问题的重点，抓住问题本质来设计的辅助思考框架。如果你能一眼就看穿问题的本质，当然不需要这么繁琐的分析方法。\u003c/p>\u003cp>\u003cstrong>【明确适用边界】\u003c/strong>\u003c/p>\u003cp>所以它更适用于信息量较大，解决较难梳理头绪需要区分事实与观点来寻求解决方案的问题，如果是天下雨了，要不要带伞？我要不要买那件新衣服？这类只有事实或全靠主观意愿决定的问题，就不存在要基于事实分析问题寻求答案了。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>A3&nbsp;&nbsp;： 微行动学习\u003c/p>\u003cp>\u003cstrong>【提问式反馈与回应-明确问题】\u003c/strong>\u003c/p>\u003cp>拆书家：通过以上拆解，大家是不是已经清楚了如何用三分法结构笔记的方法来建立起基于事实思考问题的框架，大家对步骤或是概念还有什么不理解的地方吗？\u003c/p>\u003cp>爱好者：怎么用是知道了，但是我对怎么从现状中得出问题的本质这一步觉得有疑问，不知道要怎么达成。\u003c/p>\u003cp>【提问式反馈与回应】嗯，谢谢这位伙伴，我和你确认下，是在“事实区”的现状描述，分析结论到“解释区”这一步有困难是吗？\u003c/p>\u003cp>【伙伴确认】是的\u003c/p>\u003cp>【提问式反馈与回应】好的，其他伙伴认同这个疑问吗？这个问题大家是不是都有疑惑，想再深入探讨下？\u003c/p>\u003cp>\u003cstrong>【伙伴分享】\u003c/strong>\u003c/p>\u003cp>爱好者：是的，这个很难。\u003c/p>\u003cp>\u003cstrong>【引导分组讨论问题本质】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：那给大家一点时间，我们一起来讨论下，这个问题的本质是什么呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【明确问题本质】\u003c/strong>\u003c/p>\u003cp>爱好者：我觉得最重要的是要找出从现状中发现问题得出结论方法。\u003c/p>\u003cp>拆书家：大家都这样认为么？\u003c/p>\u003cp>爱好者；是的\u003c/p>\u003cp>拆书家：那么，我们接下来请各位联系自己过去的经验，继续分组讨论下，要如何才能解决这个问题好吗？请各组将你们讨论出的解决方案写在白纸上，待会每组派一个代表分享下，你们的解决方案吧！给大家五分钟时间，开始讨论吧！\u003c/p>\u003cp>\u003cstrong>【分组讨论解决方案】\u003c/strong>\u003c/p>\u003cp>拆书家：哪个小组愿意先来分享呢？\u003c/p>\u003cp>爱好者波：我们组通过讨论，得出的方案是这样的，首先，把罗列出来的现状用蓝色的笔画出事实部分，然后，把这些事实进行分类，比如刚刚你例子中的事实有刷手机和工作不及时完成，两个类别。最后，归纳这些分类，得出结论。\u003c/p>\u003cp>拆书家：这一组能够结合我提供案例来给出解决方案，是不是很有说服力？\u003c/p>\u003cp>爱好者：是的。\u003c/p>\u003cp>拆书家：那另一组呢？\u003c/p>\u003cp>爱好者橘：我们组将方案分成了三步，和他们组大同小异。第一步：区分出事实与观点；第二步，结合事实，多角度分析，看看是知识层面的问题，还是个人意愿的问题，或是技能方面的问题，一一对应得出原因。第三步，归纳原因作出结论。\u003c/p>\u003cp>拆书家：真是厉害，这组给出的解决方案，是不是条理分明，考虑得也很细致呢？\u003c/p>\u003cp>爱好者；是的。\u003c/p>\u003cp>拆书家：那大家通过交流讨论，对于这个问题还有疑问吗？\u003c/p>\u003cp>爱好者：没有了。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>A2\u003c/p>\u003cp>\u003cstrong>【激活场景】\u003c/strong>\u003c/p>\u003cp>拆书家：那现在我们进入最后一个环节，请各位设想下未来可能会遇到的，可以用上结构笔记基于事实思考问题的场景，比如未来工作中你的下属向你咨询工作难题、生活中你的朋友向你咨询情感困惑，你的客户向你咨询产品问题，任何可能会遇到需要用三分法结构思考问题的场景。\u003c/p>\u003cp>\u003cstrong>【给出清晰指令】\u003c/strong>\u003c/p>\u003cp>这些场景下。请你运用今天所学的方法步骤，编一段小故事，几百字即可，设计出人物、背景、对话，请注意剧本要用对话的形式体现出你能用今天所学的 &nbsp; “三分法结构”五步骤，来进行问题的思考框架搭建，在纸上写出摘要即可，时间五分钟，五分钟后请人来讲讲他的剧本。\u003c/p>\u003cp>【伙伴剧本展示】\u003c/p>\u003cp>\u003cstrong>时间\u003c/strong>: 下周一\u003c/p>\u003cp>\u003cstrong>地点\u003c/strong>: 办公室\u003c/p>\u003cp>\u003cstrong>故事背景\u003c/strong>:老李的同事小明找我咨询工作问题\u003c/p>\u003cp>\u003cstrong>人物角色\u003c/strong>:老李与小明\u003c/p>\u003cp>\u003cstrong>故事内容:\u003c/strong>小明来到老李的办公室咨询老李提升工作业绩的问题\u003c/p>\u003cp>\u003cstrong>对话设计:\u003c/strong>\u003c/p>\u003cp>小明：老李，我这两个月业绩老是跟不上去，怎么办呢？没业绩怎能拿微薄的薪水还房贷呢！\u003c/p>\u003cp>老李：你这个问题太抽象了，这样吧，我教你一个思考问题的模型，你可以用它来慢慢分析，等你找到问题的根源，这样自然就有解决办法了。\u003c/p>\u003cp>小明：什么好模型，快说给我听听。\u003c/p>\u003cp>老李：这个是“三分法结构笔记”的思考模型，除了帮你梳理难题，还能拿来做学习笔记呢！\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 首先，你像我这样拿出一张白纸，用三横一线画出这样四个区域。第二步，在最上面这个区域写上你的问题，比如我怎样才能提升自己的工作业绩？第三步，你要逐条写下你目前的工作状况，像这样一、二、三、四条罗列出来。\u003c/p>\u003cp>小明：我试试，我的目前的工作现状是：1、连续两个月业绩平平，刚刚达到及格线；2、新客户开发时间不够，被事务性工作缠身，没时间开拓市场；3、感觉精力不够，没时间维护老客户，有客户流失现象；4、业绩不上去，心情就受影响服务质量好像也下降了。\u003c/p>\u003cp>老李：那请你用另外一种颜色的笔，把你现状中的事实情况标记出来。再根据事实分析你的核心问题在哪里，这个要花点时间，你得自己用心思考，但是一定是要看事实来思考哦！\u003c/p>\u003cp>小明：嗯，我画记了一下，事实情况是我业绩不佳，没有维护老客户，新客户开发得不够，服务质量比以前也下降了。总结起来问题还是我看起来很忙碌，但总是一副力不从心的状态，即没开发出足够的新市场又没维护好老客户。\u003c/p>\u003cp>老李：你有这样的觉察已经很不错了。那第四步，在下面中间这个解释区，追问自己原因，不停的问，为什么？为什么？为什么？为什么会出现这个问题，起码问四到五次，每问一次要给出自己一个答案，直到你找到问题的根源。\u003c/p>\u003cp>小明：为什么这样呢？我觉得是自己工作激情还不够，嘴上喊累没精力，实际又没有真的花精力在提升业绩上。为什么没精力呢？我觉得可能是工作态度不够好，内心觉得销售的工作实在是太辛苦了。为什么会觉得幸苦呢？因为要花很多精力与人沟通，满足客户需求，推销产品，感觉力不从心。为什么力不从心呢？其实别人也是一样的销售目标却能超标完成，我知道了。重点还是自己业务能力要提升，人家三天可以搞定一个客户，我却要七天，这里面的差距就在于我自己还需要多学习销售技巧，提升自己的销售能力。是的，就是这个原因！哎呀，老李，这个工具挺好用啊，这样不停的问下来，我突然就豁然开朗了。\u003c/p>\u003cp>老李：说了是个简单好用的思考模型呀，你能受益就好！你看还有最后一步，也就是第五步，在下面最右边的区域，写下你要怎么解决这个问题，也就是你的对策是什么？\u003c/p>\u003cp>小明：我打算向销售冠军请教下，多向高手学习销售技巧，最重要的是把学习到的知识用起来。再报个班，系统的学习和梳理下自己工作经验所得。\u003c/p>\u003cp>老李：这个很重要，希望你找到业绩提升的秘诀后，一定要付出行动去努力工作了。\u003c/p>\u003cp>小明： 是的，你这个“三分法结构”一下就理清了我的头绪，解决了我的困惑，下个月如果业绩提升了，保证请你吃饭。\u003c/p>\u003cp>\u003cstrong>故事的结果:\u003c/strong>\u003c/p>\u003cp>小明用“三分法结构”模型思考笔记里写下了问题对策，并虚心的向前辈学习请教，下个月业绩大有提升，也如约请老李吃了顿大餐。 \u003c/p>\u003cp>拆书家：非常感谢我们分享的小伙伴，你的剧本真心写得溜，简直没有一句多余的对话。再次感谢！\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>【 &nbsp; 结语 】 \u003c/p>\u003cp>那亲爱的小伙伴，通过讨论和演练环节，我本次3-3的拆解就到这里，让我们回顾下。第一个片段之后我们是不是能够在今后写学习笔记、听课笔记时，用上“三分法”结构笔记了？学会用这个结构笔记学习后，我们又通过第二个片段的现场学习知道了如何用这个结构笔记法当模型做“基于事实的思考“。同一个框架结构，既可以高效学习和吸收知识又能从大量信息中找出重点，解决问题，是不是非常实用的笔记术呢？那今天再次感谢各位的参与，让我们碰撞出了这么多的精彩，谢谢大家!\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1522900036000,"updated_at":1522900036000,"ria":true},{"id":4725,"topic":"这样做笔记，你的思考更具有逻辑性","learn_goal":"学习一套实用的思维框架——黄金三分法","remark":"亲爱的朋友，你是否遇到过下面的囧境？\r\n\r\n   热爱学习的你，常常把老师讲的内容一字不落的记下，但是用的时候却发现找不到太多有价值的信息？\r\n\r\n   认真倾听的你，一字不落的记下领导的讲话内容，但是当领导问你有什么看法的时候，却说不出自己的见解？\r\n\r\n   乐于表达的你，经常脑子里一堆灵感，但是下笔时却不知如何组织文字？\r\n\r\n如果你三个问题你都遇到过，不要焦虑，你走运了！ 这一期的拆书活动中，我将带你用20分钟的时间学习一套实用的思维框架——黄金三分法，让你做完笔记立见行动，效率翻翻，成果倍增！\r\n\r\n不但可以应用于学习、会议现场记录笔记，还可以用于思考问题，提出方案哦","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"李明轩","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>【本次 TF2-2 通过】\u003c/p>\u003cp>（学习目标：跟随我完成本次RIA现场学习，学习者能够使用“标题+三分法”来记笔记。）\u003c/p>\u003cp>大家好，我是我爱流（李明轩）。\u003c/p>\u003cp>今天我要和大家分享《聪明人都使用方格笔记本》&nbsp;\u003c/p>\u003cp>F 这本书的作者高桥政史， 曾经是日本麦肯锡咨询顾问。这本书是教读者如何\r\n通过记笔记， 整理大脑思路。&nbsp;\u003c/p>\u003cp>A 和传统的记笔记方法不同的是，这本书所教授的笔记法是基于方格本的。 据\r\n说麦肯锡等外企咨询公司都在用这种本子。 方格可以辅助我们画图表，使笔记\r\n更直观，还可以使用标题+三分法这个框架，让你的笔记更富有逻辑性。&nbsp;\u003c/p>\u003cp>B 三分法在不同的场景下有不同的运用。 如果你经常看书听课， 可以先看这本书，\r\n它教你的学习笔记法， 能帮你把学到的知识，阐述、分析、运用规划。 如果你\r\n是个上班族， 可以看看这本书，他教你的工作笔记法， 让你懂得取舍，关注问题，\r\n关注行动。 如果你经常讨论方案， 也可以看这本书，它教你的方案笔记法，能\r\n帮你有条不紊地梳理、 分析各方意见， 最后提出行动建议。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003cbr>\u003c/p>","ratings_count":1,"texts":[{"id":7773,"quote":null,"explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>I\u003c/p>\u003c/td>\u003ctd>\u003cp>2分钟\u003c/p>\u003cp>（6:00）\u003c/p>\u003c/td>\u003ctd>\u003cp>这个片段给我们展示了标题+三分法的笔记框架。\u003c/p>\u003cp>\u003cstrong>（适用范围）\u003c/strong>我们可以把它应用在现场的听课学习，方案讨论，或事后梳理。\u003c/p>\u003cp>三分法是什么，拆页很详细，我就不赘述，现在讲一下使用步骤，和两个例子。\u003c/p>\u003cp>这是我和客户在现场需求讨论中，用标题+三分法记的笔记。（\u003cstrong>展示\u003c/strong>）\u003c/p>\u003cp>第一步：A4方格纸\u003cstrong>横着放\u003c/strong>，画线分区\u003c/p>\u003cp>第二步：在0区域写上标题、这一页记得是什么\u003c/p>\u003cp>第三步：在1区域记事实，我这里把客户提出的需求列出来\u003c/p>\u003cp>第四步：在2区域是对1区域的分析，理解，就这些需求和客户讨论。\u003c/p>\u003cp>第五步：在3区域，根据前两点，确定行动计划，就是方案。这部分没有写，是交给同事完成的。\u003c/p>\u003cp>你可以看到1-&gt;2-&gt;3区域是递进的关系，由前面引出后面。\u003c/p>\u003cp>这是一次社群分享后做的作业，算是学习笔记，框架与之前相同。\u003c/p>\u003cp>不同在于0区域记录的是老师讲的内容，\u003c/p>\u003cp>1区域是结合学习内容和自己情况，做出的分析\u003c/p>\u003cp>2区域是自己接下来要怎么做\u003c/p>\u003cp>\u003cstrong>（技能点：预防异议）\u003c/strong>你可能会说太麻烦，像我以前，\u003c/p>\u003cp>有什么我都记上，需要什么找就是了。\u003c/p>\u003cp>事实上，如果现场讨论的比较激烈，大家会开始从讨论上衍生讨论，\u003c/p>\u003cp>忽略应该立足的事实，那么讨论就失去了意义。 \u003cbr>\u003c/p>\u003cp>当你熟练运用这个框架，你会发现不管讨论是否激烈，\u003c/p>\u003cp>你的思路始终是清晰的，事实-&gt;解释-&gt;做法。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>A2\u003c/p>\u003cp>（催化1）\u003c/p>\u003c/td>\u003ctd>\u003cp>2分钟\u003c/p>\u003cp>（8:00）\u003c/p>\u003c/td>\u003ctd>\u003cp>好，大家记住我刚才说的步骤了吗？ \u003cbr>\u003c/p>\u003cp>我知道你们记不住，所以我印在了拆页背面。\u003c/p>\u003cp>请按步骤在方格纸上画出四个区域，并在每个区域左上角写上对应名称，\u003cstrong>现在就做\u003c/strong>。\u003c/p>\u003cp>分步催化（1）\u003cstrong>（技能点：场景提问法）\u003c/strong>\u003c/p>\u003cp>刚开年，未来的一周，你会遇到下列哪些情境：\u003c/p>\u003cp>老板召开会议，安排新年工作重点？\u003c/p>\u003cp>新年伊始，有项目上线，需要和同事讨论方案？\u003c/p>\u003cp>想提升能力，学PPT或者其他工作技能的微课？\u003c/p>\u003cp>或者其他需要你做笔记的情境。\u003c/p>\u003cp>大家用1分钟时间想这么一个情境就行，将\u003cstrong>关键词\u003c/strong>写在\u003cstrong>标题区域\u003c/strong> ，注意，是近期。 \u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>A2\u003c/p>\u003cp>（催化2）\u003c/p>\u003c/td>\u003ctd>\u003cp>2分钟\u003c/p>\u003cp>（10:00）\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>（技能点：分布催化指令清晰，学习者能够规划出以后如何做的具体计划）\u003c/strong>\u003c/p>\u003cp>看有人动笔了，已经想出来了。\u003c/p>\u003cp>在未来的一周，你要如何运用今天所学的标题+三分法框架？ &nbsp; \u003cbr>\u003c/p>\u003cp>你可以先猜测一下，会有哪些事实，然后根据你猜测的事实，去解释，去总结做法。 \u003cbr>\u003c/p>\u003cp>在脑海中预演一下。将关键词写在对应区域。\u003c/p>\u003cp>给你2分钟时间，开动脑筋。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>5分钟\u003c/p>\u003cp>（15:00）\u003c/p>\u003c/td>\u003ctd>\u003cp>看大家已经绞尽脑汁在想了哈，现在有5分钟时间，\u003c/p>\u003cp>请大家在小组内分享一下你的规划，尽量每个人都讲~\u003c/p>\u003cp>\u003cstrong>(\u003c/strong>\u003cstrong>先把你写的笔记给你的小伙伴看一下，他是否能立刻明白你写的是什么)\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>现在时间充裕，大家有什么疑问也可以举手招呼我，为你们解答。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>2分钟\u003c/p>\u003cp>（17:00）\u003c/p>\u003c/td>\u003ctd>\u003cp>我们找一位小伙伴分享一下，他的计划。\u003c/p>\u003cp>如果你勇敢的说出来，你最终实践并掌握的可能性将大大增加哦。\u003c/p>\u003cp>\u003cstrong>（视情况做补充）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>---\u003c/strong>\u003c/p>\u003cp>学习者阿焦分享：\u003c/p>\u003cp>【场景】未来一周同事调走，项目交接给我。\u003c/p>\u003cp>【事实】同事交代的项目进展，阶段性成果，现在存在的问题，未来的计划\u003c/p>\u003cp>【解释】理出关键节点，什么时间提交什么东西，重中之重是什么。\u003c/p>\u003cp>项目取得了哪些成果，哪些成果被专家认可，哪些成果专家还有疑问。\u003c/p>\u003cp>针对专家有疑问的问题，他们现在是不是已经有了想法还没来得及做，还是现在没有想法。\u003c/p>\u003cp>【做法】根据制定出的关键节点，可以做一个倒推的计划，保证每个关键节点都有成果准时提交上去。\u003c/p>\u003cp>理顺既成成果，对于有问题的部分，如果他们有思路，我按照他们的思路继续完善；\u003c/p>\u003cp>如果他们没有思路，我就想办法，找大牛或找咨询公司一起解决问题，在下次专家审查时给出答复。\u003c/p>\u003cbr>\u003cp>\u003cstrong>---\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>好的，今天我们学习了方格笔记法的核心内容，用“标题+三分法”的框架来做笔记。这是一个方法， 光听这十几分钟是体会不出来好坏的。下去一定要用，至少写10张，再说。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1520164604000,"updated_at":1537282777000},{"id":4587,"topic":"思维整理术，方格笔记本","learn_goal":"学会如何使用方格笔记本整理思维","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"锦莉","city":"上饶"},"club":{"name":"上饶三清山分舵","city":"上饶"},"prologue":"【分组】 大家好， 欢迎大家来参加指导我的TF1-2的练级；我们首先分一下小组，我们就近三人组成一个小组，总共是三个小组。好的， 今天我选择的拆页是来自《聪明人用方格笔记本》一书。\r\n【图书介绍】 《聪明人用方格笔记本》 最有效的大脑思维整理术，作者是日本高桥政史。\r\n方格笔记本是国际著名咨询公司，包括麦肯锡，艾森哲常用的笔记方式。东京大学学生也在用方格笔记本。","ratings_count":1,"texts":[{"id":7622,"quote":"\u003cp>034\u003c/p>\u003cp>{黄金三分法之三}埃森哲公司的“Point Sheet&quot;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;全球最大的外资管理咨询公司埃森哲使用的就是一种名为”Point Sheet“的格式。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;格式中的横线和竖线都是浅绿色的，表格部分由上面的”题&nbsp;目“，左侧的”重点“&nbsp;、右侧的”行动“&nbsp;三部分组成&nbsp;。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;左侧的部分用来记录重点，右侧的部分则用来书写基于重点应采取的行动，即‘谁，在什么时间之前、需要做完什么事&nbsp;”。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;因为“重点---行动”的顺序可以按照由左到右的顺序自然得到书写整理。所以，“为何要采取这样的行动”，任何人看了都能一目了然，马上就能采取相应的行动。\u003c/p>","explains":"\u003cp>\u003cstrong>[I]&nbsp; \u003c/strong>这本《聪明人用方格笔记本》是一本专门讲笔记的书，作者是日本的高桥政史，国际著名咨询公司， 象麦肯锡，波士顿咨询公司，他们都在用方格笔记本。简单说，方格笔记本上就是布满了5*5毫米方格的笔记本，通常采用三分法来布局页面，根据你记笔记的目的采用不同的三分法。\u003c/p>\u003cp>比如今天的拆页的“题目“”重点“”行动“ 就是其中的一种三分法。这种三分法的思考方式可以帮助迅速厘清重点事项与需要采取的行动之间的直接关系， 可以让你的思路一目了然，呈现思维过程，在思考时就会自动出现行动方案从而解决问题。&nbsp; 但这种三分法的思考笔记过程不太适合学生做课堂笔记，学生则适合用另一种“板书”“发现”“总结”的三分法的思考方式。对事物思考整理的不同思考方向会有相对应的三分法参考。\u003c/p>\u003cp>笔记相当于第二大脑，它可以呈现出我们的思考方式和过程。我们从读书起就学会了记笔记。 不过，我们真的会记笔记吗？ 我们可能记过大ABCD小ABCD的笔记，可能记过密密麻麻的笔记，或许还在笔记本上贴了许多的美丽小贴纸而忘记了笔记的内容，也可能因为突然想起一件感觉特重要的事而专门慎重地买了一本硬皮笔记本，然后呢，就写了几张就没有了然后，或者会买一些小小的笔记本，想着我要随时记录我的灵感。。。。。等等。。。。\u003c/p>\u003cp>那，关于记笔记，究竟哪个方法是正确的呢？\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验]\u003c/strong>好， 现在请大家按分组，互相讨论一下，你们在上学工作所用过的笔记方法，你对于笔记本的认知，或者你认为对你有帮助的笔记本。同时对照我们今天的拆页内容，思考如果用这种思维整理和你们以前常用的记笔记方式有什么不同？\u003c/p>\u003cp>【学习者案例】&nbsp;\u003c/p>\u003cp>苏：&nbsp;锦莉姐，我就是用的你说的ABCD加abcd的笔记本，&nbsp;自己看可能还好一点，别人基本看不明白。\u003c/p>\u003cp>肖：&nbsp;嗯。&nbsp;我喜欢想起要记什么事情就专门买个笔记本，基本用两三页就不用了。&nbsp;还喜欢用小小的口袋笔记本，想&nbsp;想也没啥实际作用。\u003c/p>\u003cp>\u003cstrong>【A2&nbsp;催化应用】 \u003c/strong>好，现在，你们手上都有一个方格笔记本的纸样，想象一下下个星期你们会有一个需要记笔记的重要场合，会议会针对某项主题阐述一些重点，并会给出相应的措施解决问题。 &nbsp;请大家按照拆页上的这种“题目”“重点”“行动”三分法来做一个笔记。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>肖：&nbsp;下周我要开一个讲师团内部碰面会，需要讨论我们的工作计划行动。&nbsp;我就会用这个POINTSHEET的方式记，&nbsp;当我将主题列出，重点说明，大家针对重点展开头脑风暴，感觉具体行动我们就可以出来&nbsp;。&nbsp;然后再具体讨论行动的可行性，就很直观的解决我们讨论的主题。&nbsp;好清晰呀。&nbsp;太好了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1517221984000,"updated_at":1517743549000,"ria":true},{"id":3273,"topic":"如何记笔记，才能让自己变得更聪明","learn_goal":"掌握记笔记的方法","remark":"大家都在记笔记，有没有发现有些人的笔记让人耳目一新，有些人的笔记让人看的是眼花缭乱。上学时自己课堂笔记做得好的同学，大部分考入了公认的好大学。工作时也有很多人在做各类笔记，做得好的人晋升快。看样子笔记做得如何，对人的工作影响还是蛮大的，那您愿意和我一起探讨一下如何做好笔记，让自己变得更聪明些吗？","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"大梦","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"\u003cp>自我介绍\r\n我是王云梦，昵称肺水鱼，定居北京的山东人。工作上是一名人力资源的从业者，生活中是2个孩子的父亲。工作中不是拼命三郎，但是要求自己要有所作为。生活中不是一个全面的人，尽量做到是一个好父亲、好儿子和好丈夫。 &nbsp;\u003c/p>\u003cp>拆书和拆书帮的介绍：\u003cbr>拆书是一种学习的方法，分为个人拆书和现场拆书。个人拆书也称之为RIA便签法，R是指阅读书籍中的原文片段，I是指用自己的话重述书中原文，A是激活的自己的过往经验或日后的规划应用。现场拆书是指拆书家基于一本致用类或实用类书籍，把一本书加工成一场培训，一场活动下来，学习者的收获不亚于一场专业的培训。\u003c/p>\u003cp>拆书帮是一个基于拆书法的公益性学习型社群组织，体现形式是拆书帮在各地的分舵。\u003c/p>","ratings_count":1,"texts":[{"id":6114,"quote":null,"explains":"\u003cp>搞定三步，让您的笔记使您变得更聪明：\u003c/p>\u003cp>第一步：准备一个方格边长为5MM的笔记本。淘宝一本B5尺寸114页17.8元，淘宝一本A4尺寸80页15元\u003c/p>\u003cp>第二步：划横线分出标题区域：上侧区域根据书写习惯留出足够空间，建议3-5厘米（6-10个格子的宽度）、\u003c/p>\u003cp>第三步：画出三分线：左侧记录事实，中间记录解释、总结等，右侧行动方案\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>我在未接触方格笔记本前写的很多笔记，现在拿出来看无法回想起来当时记录的重点是什么，之间有哪些关联性。拆页中给出了我在2017年4月份参加的一次培训，当时记的笔记非常凌乱，这样的笔记重现信息的功能比较弱，主要原因是没有划分功能区域。如果划分了功能区域，再回看时，看着就清晰明了多了，也便于自己整理知识和理思路。\u003c/p>\u003cp>现场有3页未使用方格笔记本的实际案例，2张使用放个笔记本的实际案例。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>我要在参加2017年下半年的拆书帮活动时，每次都使用方格笔记本的方式记录拆书活动现场的学习，便于在一张方格笔记本内整理出自己的RIA学习，在横线上方主题区域写拆书家的主题、拆书家、拆页的书籍和日期，横线的下方左侧写I便签部分、中间写自己的A1、右侧写自己的A2，我至少写出15张方格笔记本的学习记录。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1500821916000,"updated_at":1527427108000},{"id":1697,"topic":"如何轻松高效工作","learn_goal":"学会使用方格笔记本","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"果莉","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好！我叫果莉。我全职工作是一名财务，也是一名新进的拆书家。今天我给大家带来的这本书是《聪明人用方格笔记本》作者【日】 高桥政史。这是一本教读者如何通过记笔记整理大脑思路的书。麦肯锡咨询公司、波士顿咨询公司等各大外资管理咨询公司，以及考取东大的学生聪明的人都在用“方格笔记本”原因是什么呢？因为使用方格笔记本，可以“理清大脑思路”。 整理笔记的同时，也能使工作和学习变得更有意思，效率自然也就越高。笔记是我们的“第二大脑”。 只要看一个人的笔记本，就能看出这个人的大脑。你的前途暗淡、人生迷茫是因为你在使用错误的笔记本，错误的记笔记方式。从现在开始使用方格笔记本，遵循空、雨、伞之道，开始新的笔记之路，开启新的人生模式吧!","ratings_count":0,"texts":[{"id":4258,"quote":"\u003cp>\u003cstrong>精英们坚持实践的“黄金三分法”\u003c/strong>\u003c/p>\u003cp>对信息的理解速度、学习和工作的效率会随笔记本的使用方向而改变。“横向”使用方格笔记本的话，视野会变得开阔，而且能够快速把握整体情况。\u003c/p>\u003cp>东大录取生、全美知名大学以及科研机构的研究者、外资公司的咨询顾问常按三分法(“ 黄金三分法”的简称)使用方格笔记本。\u003cstrong>让我们一起看一看“ 黄金三分法”的基本原则吧！\u003c/strong>\u003c/p>\u003cp>大多数东大录取生的笔记本都是将左右两页并作一页使用的。左侧一页用来记录老师的板书，右侧一页的左半部份用来记录老师的评语和自己的疑问、发现，右半部份则用来写解决这些问题应该采取的行动以及概括总结。\u003c/p>\u003cp>全美首屈一指的名牌学府康奈尔大学心理学系研发的“康奈尔笔记本”是先将笔记本分为三部份，分别为记录板书的部份、其左侧的思考部份以及下方的归纳总结部份。\u003cstrong>此笔记本的构造便于使用者养成按“板书”——“发现”——“总结”的顺序记笔记的习惯。\u003c/strong>\u003c/p>\u003cp>埃森哲和麦肯锡所用的：“黄金三分法”其特点为在左侧区域写重点，右侧区域写应采取的行动，也就是“谁、何时、做什么”。麦肯锡咨询顾问们严格按照“空.雨.伞”思考问题。含义如下：“空=现在的情况”“雨-对此情况的解释”“伞-依据该解释而采取的行动”看天空时发现云的情况有些不对劲—解释为可能快要小雨了—于是判断应采取“出门带伞的行动”。\u003c/p>","explains":"\u003cp>下面进行I的环节，主要有三点：1，聪明人的笔记本都有一个共同的框架-“黄金三分法”。2，聪明的学生按照“板书”——“发现”——“结论”的顺序记笔记。3，正如麦肯锡公司的“空.雨.伞”,应严格按照这种简单方式（框架）思考问题。“空=现在的情况”“雨-对此情况的解释”“伞-依据该解释而采取的行动”看天空时发现云的情况有些不对劲—解释为可能快要小雨了—于是判断应采取“出门带伞的行动”。为了让大家更深刻的了解这三个方法，我网上下了几张视觉卡片供大家理解。\u003c/p>\u003cp>其实我们拆书就是用了“空.雨.伞”的方法，原文片段就是板书，或是空=现在的情况;I用自己的话重述原文就是拆书家的发现，雨-对此情况的解释；拆书也有A2的具体行动，也就是结论“伞-依据该解释而采取的行动”。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003c/p>\u003cp>那么现在大家看了原文拆页，也听了我的I分享，现在请想一想自己之前的生活工作中，有没有经历过类似不会正确使用笔记本的事情（比如开会，读书时）。能想起来是什么样子吗？请在小组里分享一下，时间是5分钟。\u003c/p>\u003cp>学习者1：我是一名方案编辑，平时要看很多书籍。看书时我也会做笔记，但通常做完笔记就再也没有看到了。\u003c/p>\u003cp>学习者2：我们公司开会时让我做会议纪要总是记不到点子上，领导好我没有领会他的意思 。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>最后请大家用1分钟的时间写下你的A2，针对刚分享的经验，那回去之后要怎么做呢，具体哪天完成呢？\u003c/p>\u003cp>学习者1：我决定以后看书用东大名校的板书-发现-总结，这样的方式做读书笔记。\u003c/p>\u003cp>学习者2：我们公司以后开会时让我做会议纪要用黄金三分法的框架进行记录， 分为现场记录的原话——自己总结的领导原意——可实行的具体方案。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482732970000,"updated_at":1482732970000,"ria":true},{"id":1083,"topic":"《聪明人用方格笔记本》","learn_goal":"学会记下即用的记笔记方法","remark":"","level":"TF3-2","duration":60,"status":0,"type":0,"chaishujia":{"username":"丹丹们","city":"武汉"},"club":{"name":"武汉吉庆街分舵","city":"武汉"},"prologue":"在座各位亲爱的伙伴们，大家好，我就是拆书帮汉口场最著名的自High小天使丹丹们~我叫吴丹，很幸运能一路打怪升级走到现在，今天如果运气能好一点，我就能打过3-2这个级别的大怪物啦！","ratings_count":0,"texts":[{"id":3278,"quote":"\u003cp>各位伙伴有没有在工作中遇到一个事情，就是在经历了一场内容丰富、概念深奥、重点颇多的会议之后，领导找到你，“小张啊，今天的会议内容整理出来，明天早上交给我审核一遍，然后传各部门学习学习” 别的部门同事都已经下班回家各找各妈、吃香的喝辣的去了，结果这一艰巨任务就落在了陪同开会的你的肩上。不巧会上领导的发言十分深奥，艰涩难懂，你全程就只顾着记笔记，有的时候实在听不进去了还开开小差，走走神，直接影响了会议内容的全盘回顾。那一天，一个重要会议纪要整的你的办公室成了整个写字楼里最明亮的指路灯，第一遍回顾会议内容，记得不全面的地方还得赶紧趁着大家没休息的时间东问问西补补，如果有录音笔那就更好了，直接重新听一遍，会议开几个小时，你往往还得花费双倍甚至更多的时间来回顾，第二遍梳理会议流程，概括重点，第三遍精简文字，要符合会议纪要的遣词造句，修改标点符号和错别字。这样一趟下来等小张整理完会议纪要，已经明月上高楼，第二天还得顶着黑眼圈打起精神跟领导对着会议纪要回顾一下整个会议流程。万一前一天晚上烦迷糊了，领导觉得整理一个会议纪要的小事儿都办不好，这个人工作有问题啊。如果整理的出色说不定领导决定这项差事就归你担着了，长此以往，每次开会都得打足精神，一杯浓茶不离手，天天害怕上报的资料有误，创造文字内容内心焦躁，头脑费力，不到35岁说不定就成了秃顶。\u003c/p>\u003cp>对，我自己就遇到过这样的事情，当时是一场2个小时的主题培训，完全没有想到需要整理会后的记录，因为当时我是要做主持人收尾的，所以笔记记得还比较详细，大概有12页，不包括解答问题这个环节的内容。后来整理文字，光课程内容就打了1W6千字，A4纸有16页，因为概念非常多，而后，我们领导又提出来一个要求，你把它整理成PPT演讲稿。内心瞬间崩溃。\u003c/p>\u003cp>但是！今天我们即将要学习的《聪明人用方格笔记本》帮我们解决了不少问题，不仅节约了时间，提高了会议、培训之后的回顾效率，而且还可以快速的整理出一份PPT的大纲，做出高效的视觉呈现。长期坚持这样的做法，还能提升记忆力、逻辑思维能力等等。\u003c/p>\u003cp>\u003ca href=\"https://www.baidu.com/s?wd=%E6%AF%9B%E6%B3%BD%E4%B8%9C&tn=44039180_cpr&fenlei=mv6quAkxTZn0IZRqIHckPjm4nH00T1YLP1P-uHm3n161PHT1uWKh0ZwV5Hcvrjm3rH6sPfKWUMw85HfYnjn4nH6sgvPsT6KdThsqpZwYTjCEQLGCpyw9Uz4Bmy-bIi4WUvYETgN-TLwGUv3EPjbLPjDLrjn\">毛爷爷说过:“不能只低头拉车,不抬头看路。”这种记笔记的方法让我们能同时兼顾大方向和脚下的路，两手都抓的住，也能两手都抓的稳。\u003c/p>\u003cp>在介绍今天的主题片段之前，我想了解一下各位使用笔记本的一些习惯和方法，现在这份测试题请大家用5分钟的时间填写一下，一会儿我们一起看。\u003c/p>\u003cp>（测试题······）\u003c/p>","explains":"\u003cp>大家看到这个片段以后有什么想法呢？见解独到或者不理解的？\u003c/p>\u003cp>这种笔记本的使用场合是或者行业？比如说刚才提出同传、现场做整个会议的目录，我认为不是很适合，主要是来用于培训、大型会议记录、个人学习整理笔记方面\u003c/p>\u003cp>我还有一个问题，就是2和3这两个区域，2是解释，3是做法，2和3是在做笔记的时候必须马上写出来，还是你的笔记做完之后自己的归纳和整理呢？\u003c/p>\u003cp>是这样，在我有想法又不耽误记笔记的时候，我会把2和3同时写出来，也有时间来不及的时候， \u003c/p>\u003cp>我会把2记下来，3区域在我方便的时候再整理。这个主要是源于讲解人当时的速度和内容大小，在刚才毛毛讲解片段的时候，我就整理了一下\u003c/p>\u003cp>大家在工作、学习中经常用到笔记本，但是我们好像从来不知道笔记本也是有“使用说明书”的吧？今天的这个片段，就是一份“笔记本的使用说明书”，下面我把片段传上来，请大家看过以后示意我一下\u003c/p>\u003cp>0——给笔记一个标题，就像报纸上的每一小块儿内容一样，写在0区域的左手边。梳理过整页笔记的内容后，总结几个要点在0区域的右边，一般重点不超过3点。请记住，一页只有一个主题，不要主题内容过多\u003c/p>\u003cp>1——也可以说是原稿\u003c/p>\u003cp>2——讲解人对观点的延伸，或者个人的其他看法\u003c/p>\u003cp>3——行动计划的内容，可以落实的一些具体行为\u003c/p>\u003cp>这个方法基本上就是拿来即用，在你写下笔记的时候，立刻就可以写出你的想法或者行动计划，当脑子里有很多念头冒出来的时候，同时就可以记在笔记本上，当然也可以觉得内容多，只记录几个词语。\u003c/p>","interaction":"\u003cp>就相当于对过去有一个很好的回顾，也可以很清晰的看到自己设想未来的行动，同时都记录在上面。\u003c/p>\u003cp>不但可以加速学习，也可以当场涂鸦画画展示，画的很整齐\u003c/p>\u003cp>那刚才毛毛讲解的向下分类法NLP语言模式的转化我也做了记录，我并没有记录全文，只记录了一个图形，中间我只记个人理解，几句话，关键点。举得例子我就记在原文图形下方，最右边写下我自己的实际应用。\u003c/p>\u003cp>当我们记录了过去的笔记，当时当下又做了实际应用，并且记录在本子上做了练习，所以会给自己留下很深刻的印象。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":3279,"quote":"\u003cp>那我们说记笔记以后，还可以形成比较具有逻辑的PPT示稿的笔记。我提到逻辑的时候，在大家脑海里形成的图像是什么样的呢？\u003c/p>\u003cp>这样现场做的笔记很有说服力\u003c/p>\u003cp>这有一个递进的关系，就是关键词和线条，而且有颜色和箭头，用箭头来表达一个递进和我转化知识的一个过程（逻辑递进关系的图）\u003c/p>","explains":"\u003cp>展示了3个箭头，在1和2之间，一目了然的记录思路，个人案例做了个细分；\u003c/p>\u003cp>我用了强调箭头，把自己的理解延伸写出来，指出来，进行强调，当然最终还是以个人使用习惯来应用这个逻辑关系的表达\u003c/p>\u003cp>好，可以看出来方格便于画图，而且整洁\u003c/p>","interaction":"\u003cp>现在给大家每个人一张方格的纸，请大家利用这张纸重新整理一下笔记，大概3分钟\u003c/p>\u003cp>可以邀请伙伴讲解一下自己应用的效果么？\u003c/p>\u003cp>目标制定、调整与评估这个主题，我希望小孩能够进入前5名，数学、语文多少分，自己的明年个人计划，但是我觉得最重要的就是“激励”用得少，所以画圈来强调。\u003c/p>\u003cp>那你的“激励”部分你认为已经很清晰了吗？因为这个是在你的区域3，做法区域里面？\u003c/p>\u003cp>就是自己已经列出来了，心理有谱了，知道要强调去做\u003c/p>\u003cp>那刚才在练习的过程中，感觉区域1、2、3和拆书帮的RIA便签读书法是很像的， R=1阅读原文；I=2就是对原文的解释，包括自己的理解；A=3，有A1和A2，转化成了自己的行动步骤；也有人提到这个本子竖着记录有些不方便，那可以横过来记录，或者换个大一些的本子也比较适合，线装的本子。\u003c/p>\u003cp>自己记录的时候，可以强调一下区分的区域，可以折叠纸张，也可以划线，这样会更清晰一些，回顾的时候更容易。\u003c/p>\u003cp>那我们可以再总结一下方格笔记本的使用优点：\u003c/p>\u003cp>1、排版；2、书写整洁；3、适合画图、表；4、做图画创作；5、重点清晰；6、有逻辑的呈现；\u003c/p>\u003cp>7、实践个人方法\u003c/p>\u003cp>归纳、总结的时候很适合在2和3的区域去应用\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 希望大家可以在今后更高效的记笔记，谢谢\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1476089952000,"updated_at":1476089952000,"ria":true},{"id":584,"topic":"看见你的A2","learn_goal":"完成TF3-1","remark":"","level":"TF3-1","duration":50,"status":0,"type":1,"chaishujia":{"username":"Emma","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1467957408000,"updated_at":1467957408000}]};